INSERT INTO m231_art VALUES
(0,0,$m231$الديباجة$m231$,$m231$قانون رقم 151 لسنة 2020 بإصدار قانون حماية البيانات الشخصية
رئيس الجمهورية
باسم الشعب
رئيس الجمهورية
قرر مجلس النواب القانون الآتى نصه ، وقد أصدرناه :$m231$,'8d618864b487639c30407cc3615f7a70'),
(1,-1,$m231$المادة الأولى إصدار$m231$,$m231$يعمل بأحكام هذا القانون والقانون المرافق فى شأن حماية البيانات الشخصية المعالجة إلكترونيا جزئيا أو كليا لدى أى حائز أو متحكم أو معالج لها ، وذلك بالنسبة للأشخاص الطبيعيين .$m231$,'815f2ff5dcd83bb6f4ba14bb26efc008'),
(2,-1,$m231$المادة الثانية إصدار$m231$,$m231$تسرى أحكام هذا القانون والقانون المرافق له على كل من ارتكب إحدى الجرائم المنصوص عليها فى القانون المرافق متى كان الجانى من المصريين داخل الجمهورية أو خارجها ، أو كان من غير المصريين المقيمين داخل الجمهورية ، أو كان من غير المصريين خارج الجمهورية إذا كان الفعل معاقبا عليه فى الدولة التى وقع فيها تحت أى وصف قانونى وكانت البيانات محل الجريمة لمصريين أو أجانب مقيمين داخل الجمهورية .$m231$,'0d52eefc232a178e53b0417905b1fdad'),
(3,-1,$m231$المادة الثالثة إصدار$m231$,$m231$لا تسرى أحكام القانون المرافق على ما يأتى :
1 - البيانات الشخصية التى يحتفظ بها الأشخاص الطبيعيون للغير ، ويتم معالجتها للاستخدام الشخصى .
2 - البيانات الشخصية التى تتم معالجتها بغرض الحصول على البيانات الإحصائية الرسمية أو تطبيقا لنص قانونى .
3 - البيانات الشخصية التى تتم معالجتها حصرا للأغراض الإعلامية بشرط أن تكون صحيحة ودقيقة ، وألا تستخدم فى أى أغراض أخرى ، وذلك دون الإخلال بالتشريعات المنظمة للصحافة والإعلام .
4 - البيانات الشخصية المتعلقة بمحاضر الضبط القضائى والتحقيقات والدعاوى القضائية .
5 - البيانات الشخصية لدى جهات الأمن القومى ، وما تقدره لاعتبارات أخرى .
ويجب على المركز ، بناء على طلب جهات الأمن القومى ، إخطار المتحكم أو المعالج بتعديل أو محو أو عدم إظهار أو إتاحة أو تداول البيانات الشخصية ، خلال مدة زمنية محددة ، وفقا لاعتبارات الأمن القومى ، ويلتزم المتحكم أو المعالج بتنفيذ ما ورد بالإخطار خلال المدة الزمنية المحددة به .
6 - البيانات الشخصية لدى البنك المركزى المصرى والجهات الخاضعة لرقابته وإشرافه ، عدا شركات تحويل الأموال وشركات الصرافة ، على أن يراعى فى شأنهما القواعد المقررة من البنك المركزى المصرى بشأن التعامل مع البيانات الشخصية .$m231$,'c8c5a179d1478887264c71b860bd6e39'),
(4,-1,$m231$المادة الرابعة إصدار$m231$,$m231$يصدر الوزير المعنى بشئون الاتصالات وتكنولوجيا المعلومات اللائحة التنفيذية للقانون المرافق خلال ستة أشهر من تاريخ العمل بهذا القانون .$m231$,'b1c7b5deb016263c4c6a58f51465dced'),
(5,-1,$m231$المادة الخامسة إصدار$m231$,$m231$تختص المحاكم الاقتصادية بنظر الجرائم التى ترتكب بالمخالفة لأحكام القانون المرافق .$m231$,'d38418ec354eeba990df3fde028b91f7'),
(6,-1,$m231$المادة السادسة إصدار$m231$,$m231$يلتزم المخاطبون بأحكام هذا القانون بتوفيق أوضاعهم طبقا لأحكام القانون المرافق ولائحته التنفيذية ، وذلك خلال سنة من تاريخ صدور هذه اللائحة .$m231$,'42a42b1c9f3b306f67b8f43f75e43e2d'),
(7,-1,$m231$المادة السابعة إصدار$m231$,$m231$ينشر هذا القانون فى الجريدة الرسمية ، ويعمل به بعد مضى ثلاثة أشهر من اليوم التالى لتاريخ نشره .
يبصم هذا القانون بخاتم الدولة ، وينفذ كقانون من قوانينها .
صدر برئاسة الجمهورية فى 22 ذى القعدة سنة 1441 هـ
( الموافق 13 يوليو سنة 2020 م ) .
عبد الفتاح السيسى$m231$,'fea5af411eaaf6eeca5ebb56f5912be2'),
(1,0,$m231$المادة 1$m231$,$m231$فى تطبيق أحكام هذا القانون ، يقصد بالكلمات والعبارات التالية المعنى المبين قرين كل منها :
البيانات الشخصية : أى بيانات متعلقة بشخص طبيعى محدد ، أو يمكن تحديده بشكل مباشر أو غير مباشر عن طريق الربط بين هذه البيانات وأى بيانات أخرى كالاسم ، أو الصوت ، أو الصورة ، أو رقم تعريفى ، أو محدد للهوية عبر الإنترنت ، أو أى بيانات تحدد الهوية النفسية ، أو الصحية ، أو الاقتصادية ، أو الثقافية ، أو الاجتماعية .
المعالجة : أى عملية إلكترونية أو تقنية لكتابة البيانات الشخصية ، أو تجميعها ، أو تسجيلها ، أو حفظها ، أو تخزينها ، أو دمجها ، أو عرضها ، أو إرسالها ، أو استقبالها ، أو تداولها ، أو نشرها ، أو محوها ، أو تغييرها ، أو تعديلها ، أو استرجاعها أو تحليلها وذلك باستخدام أى وسيط من الوسائط أو الأجهزة الإلكترونية أو التقنية سواء تم ذلك جزئيا أو كليا .
البيانات الشخصية الحساسة : البيانات التى تفصح عن الصحة النفسية أو العقلية أو البدنية أو الجينية ، أو بيانات القياسات الحيوية "البيومترية" أو البيانات المالية أو المعتقدات الدينية أو الآراء السياسية أو الحالة الأمنية ، وفى جميع الأحوال تعد بيانات الأطفال من البيانات الشخصية الحساسة .
الشخص المعنى بالبيانات : أى شخص طبيعى تنسب إليه بيانات شخصية معالجة إلكترونيا تدل عليه قانونا أو فعلا ، وتمكن من تمييزه عن غيره .
الحائز : أى شخص طبيعى أو اعتبارى ، يحوز ويحتفظ قانونيا أو فعليا ببيانات شخصية فى أى صورة ، أو على أى وسيلة تخزين سواء أكان هو المنشئ للبيانات ، أم انتقلت إليه حيازتها بأى صورة .
المتحكم : أى شخص طبيعى أو اعتبارى يكون له بحكم أو طبيعة عمله ، الحق فى الحصول على البيانات الشخصية وتحديد طريقة وأسلوب ومعايير الاحتفاظ بها ، أو معالجتها والتحكم فيها طبقا للغرض المحدد أو نشاطه .
المعالج : أى شخص طبيعى أو اعتبارى مختص بطبيعة عمله ، بمعالجة البيانات الشخصية لصالحه أو لصالح المتحكم بالاتفاق معه ووفقا لتعليماته .
إتاحة البيانات الشخصية : كل وسيلة تحقق اتصال علم الغير بالبيانات الشخصية كالاطلاع أو التداول أو النشر أو النقل أو الاستخدام أو العرض أو الإرسال أو الاستقبال أو الإفصاح عنها .
أمن البيانات : إجراءات وعمليات تقنية وتنظيمية من شأنها الحفاظ على خصوصية البيانات الشخصية وسريتها وسلامتها ووحدتها وتكاملها فيما بينها .
خرق وانتهاك البيانات الشخصية : كل دخول غير مرخص به إلى بيانات شخصية أو وصول غير مشروع لها ، أو أى عملية غير مشروعة لنسخ أو إرسال أو توزيع أو تبادل أو نقل أو تداول يهدف إلى الكشف أو الإفصاح عن البيانات الشخصية أو إتلافها أو تعديلها أثناء تخزينها أو نقلها أو معالجتها .
حركة البيانات الشخصية عبر الحدود : نقل البيانات أو إتاحتها أو تسجيلها أو تخزينها أو تداولها أو نشرها أو استخدامها أو عرضها أو إرسالها أو استقبالها أو استرجاعها أو معالجتها ، من داخل النطاق الجغرافى لجمهورية مصر العربية إلى خارجه أو العكس .
التسويق الإلكترونى : إرسال أى رسالة أو بيان أو محتوى إعلانى أو تسويقى بأى وسيلة تقنية أيا كانت طبيعتها أو صورتها تستهدف بشكل مباشر أو غير مباشر ترويج سلع أو خدمات أو التماسات أو طلبات تجارية أو سياسية أو اجتماعية أو خيرية موجهة إلى أشخاص بعينهم .
جهات الأمن القومى : رئاسة الجمهورية ووزارة الدفاع ووزارة الداخلية وجهاز المخابرات العامة وهيئة الرقابة الإدارية .
المركز : مركز حماية البيانات الشخصية .
الترخيص : وثيقة رسمية تصدر عن المركز للشخص الاعتبارى تمنحه من خلالها الحق فى مزاولة نشاط جمع البيانات الشخصية الإلكترونية أو تلقيها أو نقلها أو تخزينها أو معالجتها أو القيام بأنشطة التسويق الإلكترونى أو كل ما سبق والتعامل عليها بأى صورة ، وتحدد التزامات المرخص له وفق القواعد والشروط والإجراءات والمعايير الفنية المحددة باللائحة التنفيذية لهذا القانون ، وذلك لمدة ثلاث سنوات قابلة للتجديد لمدد أخرى .
التصريح : وثيقة رسمية تصدر عن المركز للشخص الطبيعى أو الاعتبارى تمنحه من خلالها الحق فى ممارسة نشاط جمع البيانات الشخصية الإلكترونية أو تخزينها أو نقلها أو معالجتها أو القيام بأنشطة التسويق الإلكترونى أو كل ما سبق والتعامل عليها بأى صورة ، أو لأداء مهمة أو مهام معينة ، وتحدد هذه الوثيقة التزامات المصرح له وفق القواعد والشروط والإجراءات والمعايير الفنية المحددة باللائحة التنفيذية ، لمدة مؤقتة لا تجاوز سنة ، ويجوز تجديدها لأكثر من مدة .
الاعتماد : شهادة تصدر عن المركز تفيد أن الشخص الطبيعى أو الاعتبارى قد استوفى جميع المتطلبات الفنية والقانونية والتنظيمية المحددة باللائحة التنفيذية لهذا القانون ويكون بموجبها مؤهلا لتقديم الاستشارات فى مجال حماية البيانات الشخصية .
الوزير المختص : الوزير المعنى بشئون الاتصالات وتكنولوجيا المعلومات .$m231$,'e2799b77b7bbf86a5b37406cf6becd92'),
(2,0,$m231$المادة 2$m231$,$m231$لا يجوز جمع البيانات الشخصية أو معالجتها أو الإفصاح عنها أو إفشائها بأى وسيلة من الوسائل إلا بموافقة صريحة من الشخص المعنى بالبيانات ، أو فى الأحوال المصرح بها قانونا .
ويكون للشخص المعنى بالبيانات الحقوق الآتية :
1 - العلم بالبيانات الشخصية الخاصة به الموجودة لدى أى حائز أو متحكم أو معالج والاطلاع عليها والوصول إليها أو الحصول عليها .
2 - العدول عن الموافقة المسبقة على الاحتفاظ ببياناته الشخصية أو معالجتها .
3 - التصحيح أو التعديل أو المحو أو الإضافة أو التحديث للبيانات الشخصية .
4 - تخصيص المعالجة فى نطاق محدد .
5 - العلم والمعرفة بأى خرق أو انتهاك لبياناته الشخصية .
6 - الاعتراض على معالجة البيانات الشخصية أو نتائجها متى تعارضت مع الحقوق والحريات الأساسية للشخص المعنى بالبيانات .
وباستثناء البند (5) من الفقرة السابقة ، يؤدى الشخص المعنى بالبيانات مقابل تكلفة الخدمة المقدمة إليه من المتحكم أو المعالج فيما يخص ممارسته لحقوقه ، ويتولى المركز إصدار قرارات تحديد هذا المقابل بما لا يجاوز عشرين ألف جنيه .$m231$,'bac52e4d9b1a41aa9ffdc50a331937c0'),
(3,0,$m231$المادة 3$m231$,$m231$يجب لجمع البيانات الشخصية ومعالجتها والاحتفاظ بها ، توافر الشروط الآتية :
1 - أن تجمع البيانات الشخصية لأغراض مشروعة ومحددة ومعلنة للشخص المعنى .
2 - أن تكون صحيحة وسليمة ومؤمنة .
3 - أن تعالج بطريقة مشروعة وملائمة للأغراض التى تم تجميعها من أجلها .
4 - ألا يتم الاحتفاظ بها لمدة أطول من المدة اللازمة للوفاء بالغرض المحدد لها .
وتحدد اللائحة التنفيذية لهذا القانون السياسات والإجراءات والضوابط والمعايير القياسية للجمع والمعالجة والحفظ والتأمين لهذه البيانات .$m231$,'60ed3108b1732310ef02958adc585d10'),
(4,0,$m231$المادة 4$m231$,$m231$مع مراعاة أحكام المادة (12) من هذا القانون ، يلتزم المتحكم بما يأتى :
1 - الحصول على البيانات الشخصية أو تلقيها من الحائز أو من الجهات المختصة بتزويده بها بحسب الأحوال بعد موافقة الشخص المعنى بالبيانات ، أو فى الأحوال المصرح بها قانونا .
2 - التأكد من صحة البيانات الشخصية واتفاقها وكفايتها مع الغرض المحدد لجمعها .
3 - وضع طريقة وأسلوب ومعايير المعالجة طبقا للغرض المحدد ، ما لم يقرر تفويض المعالج فى ذلك بموجب تعاقد مكتوب .
4 - التأكد من انطباق الغرض المحدد من جمع البيانات الشخصية لأغراض معالجتها .
5 - القيام بعمل أو الامتناع عن عمل يكون من شأنه إتاحة البيانات الشخصية إلا فى الأحوال المصرح بها قانونا .
6 - اتخاذ جميع الإجراءات التقنية والتنظيمية وتطبيق المعايير القياسية اللازمة لحماية البيانات الشخصية وتأمينها حفاظا على سريتها ، وعدم اختراقها أو إتلافها أو تغييرها أو العبث بها قبل أى إجراء غير مشروع .
7 - محو البيانات الشخصية لديه فور انقضاء الغرض المحدد منها ، أما فى حال الاحتفاظ بها لأى سبب من الأسباب المشروعة بعد انتهاء الغرض ، فيجب ألا تبقى فى صورة تسمح بتحديد الشخص المعنى بالبيانات .
8 - تصحيح أى خطأ بالبيانات الشخصية فور إبلاغه أو علمه به .
9 - إمساك سجل خاص للبيانات ، على أن يتضمن وصف فئات البيانات الشخصية لديه ، وتحديد من سيفصح لهم عن هذه البيانات أو يتيحها لهم وسنده والمدد الزمنية وقيودها ونطاقها وآليات محو البيانات الشخصية لديه أو تعديلها وأى بيانات أخرى متعلقة بنقل تلك البيانات الشخصية عبر الحدود ووصف الإجراءات التقنية والتنظيمية الخاصة بأمن البيانات .
10 - الحصول على ترخيص أو تصريح من المركز للتعامل مع البيانات الشخصية .
11 - يلتزم المتحكم خارج جمهورية مصر العربية بتعيين ممثل له فى جمهورية مصر العربية وذلك على النحو الذى تبينه اللائحة التنفيذية .
12 - توفير الإمكانيات اللازمة لإثبات التزامه بتطبيق أحكام هذا القانون وتمكين المركز من التفتيش والرقابة للتأكد من ذلك .
وفى حال وجود أكثر من متحكم يلتزم كل منهم بجميع الالتزامات المنصوص عليها فى هذا القانون ، وللشخص المعنى ممارسة حقوقه تجاه كل متحكم على حدة .
وتحدد اللائحة التنفيذية لهذا القانون السياسات والإجراءات والضوابط والمعايير الفنية لتلك الالتزامات .$m231$,'4d70bd6698f6b5c1e69a8e6ba1a80b84'),
(5,0,$m231$المادة 5$m231$,$m231$مع مراعاة أحكام المادة (12) من هذا القانون ، يلتزم معالج البيانات الشخصية بما يأتى :
1 - إجراء المعالجة وتنفيذها طبقا للقواعد المنظمة لذلك بهذا القانون ولائحته التنفيذية ووفقا للحالات المشروعة والقانونية وبناء على التعليمات المكتوبة الواردة إليه من المركز أو المتحكم أو من أى ذى صفة بحسب الأحوال ، وبصفة خاصة فيما يتعلق بنطاق عملية المعالجة وموضوعها وطبيعتها ونوع البيانات الشخصية واتفاقها وكفايتها مع الغرض المحدد له .
2 - أن تكون أغراض المعالجة وممارستها مشروعة ، ولا تخالف النظام العام أو الآداب العامة .
3 - عدم تجاوز الغرض المحدد للمعالجة ومدتها ، ويجب إخطار المتحكم أو الشخص المعنى بالبيانات أو كل ذى صفة ، بحسب الأحوال ، بالمدة اللازمة للمعالجة .
4 - محو البيانات الشخصية بانقضاء مدة المعالجة أو تسليمها للمتحكم .
5 - القيام بعمل أو الامتناع عن عمل يكون من شأنه إتاحة البيانات الشخصية أو نتائج المعالجة إلا فى الأحوال المصرح بها قانونا .
6 - عدم إجراء أى معالجة للبيانات الشخصية تتعارض مع غرض المتحكم فيها أو نشاطه إلا إذا كان ذلك بغرض إحصائى أو تعليمى ولا يهدف للربح ودون الإخلال بحرمة الحياة الخاصة .
7 - حماية وتأمين عملية المعالجة والوسائط والأجهزة الإلكترونية المستخدمة فى ذلك وما عليها من بيانات شخصية .
8 - عدم إلحاق أى ضرر بالشخص المعنى بالبيانات بشكل مباشر أو غير مباشر .
9 - إعداد سجل خاص بعمليات المعالجة لديه ، على أن يتضمن فئات المعالجة التى يجريها نيابة عن أى متحكم وبيانات الاتصال به ومسئول حماية البيانات لديه ، والمدد الزمنية للمعالجة وقيودها ونطاقها وآليات محو البيانات الشخصية لديه أو تعديلها ، ووصفا للإجراءات التقنية والتنظيمية الخاصة بأمن البيانات وعمليات المعالجة .
10 - توفير الإمكانيات لإثبات التزامه بتطبيق أحكام هذا القانون عند طلب المتحكم وتمكين المركز من التفتيش والرقابة للتأكد من التزامه بذلك .
11 - الحصول على ترخيص أو تصريح من المركز للتعامل على البيانات الشخصية .
12 - يلتزم المعالج خارج جمهورية مصر العربية بتعيين ممثل له فى جمهورية مصر العربية وذلك على النحو الذى تبينه اللائحة التنفيذية .
وفى حال وجود أكثر من معالج ، يلتزم كل منهم بجميع الالتزامات المنصوص عليها فى هذا القانون وذلك فى حال عدم وجود عقد يحدد التزامات ومسئوليات كل منهم بوضوح .
وتحدد اللائحة التنفيذية لهذا القانون السياسات والإجراءات والضوابط والشروط والتعليمات والمعايير القياسية لتلك الالتزامات .$m231$,'23b47e74464cece815e8fae0df588224'),
(6,0,$m231$المادة 6$m231$,$m231$تعد المعالجة الإلكترونية مشروعة وقانونية فى حال توفر أى من الحالات الآتية :
1 - موافقة الشخص المعنى بالبيانات على إجراء المعالجة من أجل تحقيق غرض محدد أو أكثر .
2 - أن تكون المعالجة لازمة وضرورية تنفيذا لالتزام تعاقدى أو تصرف قانونى أو لإبرام عقد لصالح الشخص المعنى بالبيانات ، أو لمباشرة أى من إجراءات المطالبة بالحقوق القانونية له أو الدفاع عنها .
3 - تنفيذ التزام ينظمه القانون أو أمر من جهات التحقيق المختصة أو بناء على حكم قضائى .
4 - تمكين المتحكم من القيام بالتزاماته أو أى ذى صفة من ممارسة حقوقه المشروعة ، ما لم يتعارض ذلك مع الحقوق والحريات الأساسية للشخص المعنى بالبيانات .$m231$,'d36058eb780ccbb56291bf505dbb21f7'),
(7,0,$m231$المادة 7$m231$,$m231$يلتزم كل من المتحكم والمعالج بحسب الأحوال حال علمه بوجود خرق أو انتهاك للبيانات الشخصية لديه بإبلاغ المركز خلال اثنتين وسبعين ساعة ، وفى حال كان هذا الخرق أو الانتهاك متعلقا باعتبارات حماية الأمن القومى فيكون الإبلاغ فوريا ، وعلى المركز وفى جميع الأحوال إخطار جهات الأمن القومى بالواقعة فورا ، كما يلتزم بموافاة المركز خلال اثنتين وسبعين ساعة من تاريخ علمه بما يأتى :
1 - وصف طبيعة الخرق أو الانتهاك ، وصورته وأسبابه والعدد التقريبى للبيانات الشخصية وسجلاتها .
2 - بيانات مسئول حماية البيانات الشخصية لديه .
3 - الآثار المحتملة لحادث الخرق أو الانتهاك .
4 - وصف الإجراءات المتخذة والمقترح تنفيذها لمواجهة هذا الخرق أو الانتهاك والتقليل من آثاره السلبية .
5 - توثيق أى خرق أو انتهاك للبيانات الشخصية ، والإجراءات التصحيحية المتخذة لمواجهته .
6 - أى وثائق أو معلومات أو بيانات يطلبها المركز .
وفى جميع الأحوال يجب على المتحكم والمعالج ، بحسب الأحوال ، إخطار الشخص المعنى بالبيانات خلال ثلاثة أيام عمل من تاريخ الإبلاغ وما تم اتخاذه من إجراءات .
وتحدد اللائحة التنفيذية لهذا القانون الإجراءات الخاصة بالإبلاغ والإخطار .$m231$,'ddca616decc2f0f04b839de6af409d97'),
(8,0,$m231$المادة 8$m231$,$m231$ينشأ بالمركز سجل لقيد مسئولى حماية البيانات الشخصية ، وتحدد اللائحة التنفيذية لهذا القانون شروط القيد وإجراءاته وآليات التسجيل .
ويلتزم الممثل القانونى للشخص الاعتبارى لأى متحكم أو معالج بأن يعين داخل كيانه القانونى وهيكله الوظيفى موظفا مختصا مسئولا عن حماية البيانات الشخصية ، وذلك بقيده فى سجل مسئولى حماية البيانات الشخصية بالمركز ، ويعلن عن ذلك .
ويكون الشخص الطبيعى المتحكم أو المعالج هو المسئول عن تطبيق أحكام هذا القانون .$m231$,'90a4c4f559da8de8d997eab08af995ae'),
(9,0,$m231$المادة 9$m231$,$m231$يكون مسئول حماية البيانات الشخصية مسئولا عن تنفيذ أحكام القانون ولائحته التنفيذية وقرارات المركز ، ومراقبة الإجراءات المعمول بها داخل كيانه والإشراف عليها ، وتلقى الطلبات المتعلقة بالبيانات الشخصية وفقا لأحكام هذا القانون .
ويلتزم على الأخص بالآتى :
1 - إجراء التقييم والفحص الدورى لنظم حماية البيانات الشخصية ومنع اختراقها ، وتوثيق نتائج التقييم وإصدار التوصيات اللازمة لحمايتها .
2 - العمل كنقطة اتصال مباشرة مع المركز وتنفيذ قراراته ، فيما يخص تطبيق أحكام هذا القانون .
3 - تمكين الشخص المعنى بالبيانات من ممارسة حقوقه المنصوص عليها فى هذا القانون .
4 - إخطار المركز فى حال وجود أى خرق أو انتهاك للبيانات الشخصية لديه .
5 - الرد على الطلبات المقدمة من الشخص المعنى بالبيانات أو كل ذى صفة ، والرد على المركز فى التظلمات المقدمة إليه من أى منهما وفقا لأحكام هذا القانون .
6 - متابعة القيد والتحديث لسجل البيانات الشخصية لدى المتحكم أو سجل عمليات المعالجة لدى المعالج ، بما يكفل ضمان دقة البيانات والمعلومات المقيدة به .
7 - إزالة أى مخالفات متعلقة بالبيانات الشخصية داخل كيانه ، واتخاذ الإجراءات التصحيحية حيالها .
8 - تنظيم البرامج التدريبية اللازمة لموظفى كيانه ، لتأهيلهم بما يتناسب مع متطلبات هذا القانون .
وتحدد اللائحة التنفيذية لهذا القانون الالتزامات والإجراءات والمهام الأخرى التى يجب على مسئول حماية البيانات الشخصية القيام بها .$m231$,'748bac8af6259a2685bf65e12ca3e882'),
(10,0,$m231$المادة 10$m231$,$m231$يلتزم كل من المتحكم والمعالج والحائز عند طلب إتاحة البيانات الشخصية بالإجراءات الآتية :
1 - أن يكون بناء على طلب كتابى يقدم إليه من ذى صفة أو وفقا لسند قانونى .
2 - التحقق من توافر المستندات اللازمة لتنفيذ الإتاحة والاحتفاظ بها .
3 - البت فى الطلب ومستنداته خلال ستة أيام عمل من تاريخ تقديمه إليه ، وعند صدور قرار بالرفض يجب أن يكون الرفض مسببا ، ويعتبر مضى المدة المشار إليها دون رد فى حكم الرفض .$m231$,'9d5dfefc8231b7d4a4ff388809f6f8f1'),
(11,0,$m231$المادة 11$m231$,$m231$يكون للدليل الرقمى المستمد من البيانات الشخصية طبقا لأحكام هذا القانون ذات الحجية فى الإثبات المقررة للأدلة المستمدة من البيانات والمعلومات الخطية متى استوفت المعايير والشروط الفنية الواردة باللائحة التنفيذية لهذا القانون .$m231$,'661e019d7016fc449517ef92f4932444'),
(12,0,$m231$المادة 12$m231$,$m231$يحظر على المتحكم أو المعالج سواء كان شخصا طبيعيا أو اعتباريا جمع بيانات شخصية حساسة أو نقلها أو تخزينها أو حفظها أو معالجتها أو إتاحتها إلا بترخيص من المركز .
وفيما عدا الأحوال المصرح بها قانونا ، يلزم الحصول على موافقة كتابية وصريحة من الشخص المعنى .
وفى حالة إجراء أى عملية مما ذكر تتعلق ببيانات الأطفال ، يلزم موافقة ولى الأمر .
ويجب ألا تكون مشاركة الطفل فى لعبة أو مسابقة أو أى نشاط آخر مشروطة بتقديم بيانات شخصية للطفل تزيد على ما هو ضرورى للمشاركة فى ذلك .
وذلك كله وفقا للمعايير والضوابط التى تحددها اللائحة التنفيذية لهذا القانون .$m231$,'1b6cc1384de1c88bd063dbe049e94b92'),
(13,0,$m231$المادة 13$m231$,$m231$بالإضافة إلى الالتزامات الواردة بالمادة (9) من هذا القانون ، يلتزم مسئول حماية البيانات الشخصية وتابعوه لدى المتحكم أو المعالج باتباع واستيفاء السياسات والإجراءات التأمينية اللازمة لعدم خرق البيانات الشخصية الحساسة أو انتهاكها .$m231$,'bb32f8e36a0ffeed05b7374de9998141'),
(14,0,$m231$المادة 14$m231$,$m231$يحظر إجراء عمليات نقل للبيانات الشخصية التى تم جمعها أو تجهيزها للمعالجة إلى دولة أجنبية أو تخزينها أو مشاركتها إلا بتوافر مستوى من الحماية لا يقل عن المستوى المنصوص عليه فى هذا القانون ، وبترخيص أو تصريح من المركز .
وتحدد اللائحة التنفيذية لهذا القانون السياسات والمعايير والضوابط والقواعد اللازمة لنقل أو تخزين أو مشاركة أو معالجة أو إتاحة البيانات الشخصية عبر الحدود وحمايتها .$m231$,'377bb637d0b390e17a4ebbc420bb10ec'),
(15,0,$m231$المادة 15$m231$,$m231$استثناء من حكم المادة (14) من هذا القانون ، يجوز فى حالة الموافقة الصريحة للشخص المعنى بالبيانات أو من ينوب عنه نقل أو مشاركة أو تداول أو معالجة البيانات الشخصية إلى دولة لا يتوافر فيها مستوى الحماية المشار إليه فى المادة السابقة ، وذلك فى الحالات الآتية :
1 - المحافظة على حياة الشخص المعنى بالبيانات ، وتوفير الرعاية الطبية أو العلاج أو إدارة الخدمات الصحية له .
2 - تنفيذ التزامات بما يضمن إثبات حق أو ممارسته أمام جهات العدالة أو الدفاع عنه .
3 - إبرام عقد ، أو تنفيذ عقد مبرم بالفعل ، أو سيتم إبرامه بين المسئول عن المعالجة والغير ، وذلك لمصلحة الشخص المعنى بالبيانات .
4 - تنفيذ إجراء خاص بتعاون قضائى دولى .
5 - وجود ضرورة أو إلزام قانونى لحماية المصلحة العامة .
6 - إجراء تحويلات نقدية إلى دولة أخرى وفقا لتشريعاتها المحددة والسارية .
7 - إذا كان النقل أو التداول يتم تنفيذا لاتفاق دولى ثنائى أو متعدد الأطراف تكون جمهورية مصر العربية طرفا فيه .$m231$,'b248c780401b6de87387c29e030b9a0b'),
(16,0,$m231$المادة 16$m231$,$m231$يجوز للمتحكم أو المعالج ، بحسب الأحوال ، إتاحة البيانات الشخصية لمتحكم أو معالج آخر خارج جمهورية مصر العربية بترخيص من المركز متى توافرت الشروط الآتية :
1 - اتفاق طبيعة عمل كل من المتحكمين أو المعالجين ، أو وحدة الغرض الذى يحصلان بموجبه على البيانات الشخصية .
2 - توافر المصلحة المشروعة لدى كل من المتحكمين أو المعالجين للبيانات الشخصية أو لدى الشخص المعنى بالبيانات .
3 - ألا يقل مستوى الحماية القانونية والتقنية للبيانات الشخصية لدى المتحكم أو المعالج الموجودة بخارج جمهورية مصر العربية عن المستوى المتوافر فى جمهورية مصر العربية .
وتحدد اللائحة التنفيذية لهذا القانون الاشتراطات والإجراءات والاحتياطات والمعايير والقواعد اللازمة لذلك .$m231$,'ae814b35563f2a81fbffefed802e55cf'),
(17,0,$m231$المادة 17$m231$,$m231$يحظر إجراء أى اتصال إلكترونى بغرض التسويق المباشر للشخص المعنى بالبيانات ، إلا بتوافر الشروط الآتية :
1 - الحصول على موافقة من الشخص المعنى بالبيانات .
2 - أن يتضمن الاتصال هوية منشئه ومرسله .
3 - أن يكون للمرسل عنوان صحيح وكاف للوصول إليه .
4 - الإشارة إلى أن الاتصال الإلكترونى مرسل لأغراض التسويق المباشر .
5 - وضع آليات واضحة وميسرة لتمكين الشخص المعنى بالبيانات من رفض الاتصال الإلكترونى أو العدول عن موافقته على إرسالها .$m231$,'e3544af2cceda422a21e02637951afd8'),
(18,0,$m231$المادة 18$m231$,$m231$يلتزم المرسل لأى اتصال إلكترونى بغرض التسويق المباشر بالالتزامات الآتية :
1 - الغرض التسويقى المحدد .
2 - عدم الإفصاح عن بيانات الاتصال للشخص المعنى بالبيانات .
3 - الاحتفاظ بسجلات إلكترونية مثبت بها موافقة الشخص المعنى بالبيانات وتعديلاتها ، أو عدم اعتراضه على استمراره ، بشأن تلقى الاتصال الإلكترونى التسويقى وذلك لمدة ثلاث سنوات من تاريخ آخر إرسال .
وتحدد اللائحة التنفيذية لهذا القانون القواعد والشروط والضوابط المتعلقة بالتسويق الإلكترونى المباشر .$m231$,'c2e210859b3bc0aec62f510bca0fa093'),
(19,0,$m231$المادة 19$m231$,$m231$تنشأ هيئة عامة اقتصادية تسمى «مركز حماية البيانات الشخصية» ، تتبع الوزير المختص ، وتكون لها الشخصية الاعتبارية ، ويكون مقرها الرئيس محافظة القاهرة أو إحدى المحافظات المجاورة لها ، وتهدف إلى حماية البيانات الشخصية وتنظيم معالجتها وإتاحتها ، ولها فى سبيل تحقيق أهدافها أن تباشر جميع الاختصاصات المنصوص عليها بهذا القانون ، ولها على الأخص الآتى :
وضع وتطوير السياسات والخطط الاستراتيجية والبرامج اللازمة لحماية البيانات الشخصية ، والقيام على تنفيذها .
توحيد سياسات وخطط حماية ومعالجة البيانات الشخصية داخل الجمهورية .
وضع وتطبيق القرارات والضوابط والتدابير والإجراءات والمعايير الخاصة بحماية البيانات الشخصية .
وضع إطار إرشادى لمدونات السلوك الخاصة بحماية البيانات الشخصية ، واعتماد مدونات السلوك الخاصة بحماية البيانات الشخصية بالجهات المختلفة .
التنسيق والتعاون مع جميع الجهات والأجهزة الحكومية وغير الحكومية فى ضمان إجراءات حماية البيانات الشخصية ، والتواصل مع جميع المبادرات ذات الصلة .
دعم تطوير كفاءة الكوادر البشرية العاملة فى جميع الجهات الحكومية وغير الحكومية القائمة على حماية البيانات الشخصية .
إصدار التراخيص أو التصاريح والموافقات والتدابير المختلفة المتعلقة بحماية البيانات الشخصية وتطبيق أحكام هذا القانون .
اعتماد الجهات والأفراد ، ومنحهم التصاريح اللازمة التى تتيح لهم تقديم الاستشارات فى إجراءات حماية البيانات الشخصية .
تلقى الشكاوى والبلاغات المتعلقة بأحكام هذا القانون ، وإصدار القرارات اللازمة فى شأنها .
إبداء الرأى فى مشروعات القوانين والاتفاقيات الدولية التى تنظم البيانات الشخصية أو تتعلق أو تنعكس نصوصها بصورة مباشرة أو غير مباشرة عليها .
الرقابة والتفتيش على المخاطبين بأحكام هذا القانون ، واتخاذ الإجراءات القانونية اللازمة .
التحقق من شروط حركة البيانات عبر الحدود ، واتخاذ القرارات المنظمة لها .
تنظيم المؤتمرات وورش العمل والدورات التدريبية والتثقيفية ، وإصدار المطبوعات لنشر الوعى والتثقيف للأفراد والجهات حول حقوقهم فيما يتعلق بالتعامل على البيانات الشخصية .
تقديم جميع أنواع الخبرة والاستشارات المتعلقة بحماية البيانات الشخصية ، وعلى الأخص لجهات التحقيق والجهات القضائية .
إبرام الاتفاقيات ومذكرات التفاهم والتنسيق والتعاون وتبادل الخبرات مع الجهات الدولية ذات الصلة بعمل المركز وفقا للقواعد والإجراءات المقررة فى هذا الشأن .
إصدار الدوريات الخاصة بتحديث إجراءات الحماية بما يتوافق مع أنشطة القطاعات المختلفة وتوصيات المركز فى شأنها .
إعداد وإصدار تقرير سنوى عن حالة حماية البيانات الشخصية فى جمهورية مصر العربية .$m231$,'13f7584f479b503510622e27776c6dbb'),
(20,0,$m231$المادة 20$m231$,$m231$يكون للمركز مجلس إدارة ، يشكل برئاسة الوزير المختص ، وعضوية كل من :
1 - ممثل عن وزارة الدفاع يختاره وزير الدفاع .
2 - ممثل عن وزارة الداخلية يختاره وزير الداخلية .
3 - ممثل عن جهاز المخابرات العامة يختاره رئيس الجهاز .
4 - ممثل عن هيئة الرقابة الإدارية يختاره رئيس الهيئة .
5 - ممثل عن هيئة تنمية صناعة تكنولوجيا المعلومات يختاره رئيس مجلس إدارة الهيئة .
6 - ممثل عن الجهاز القومى لتنظيم الاتصالات يختاره رئيس مجلس إدارة الجهاز .
7 - الرئيس التنفيذى للمركز .
8 - ثلاثة من ذوى الخبرة يختارهم الوزير المختص .
وتكون مدة عضوية مجلس الإدارة ثلاث سنوات قابلة للتجديد ، ويصدر بتشكيله ، وتحديد المعاملة المالية لأعضائه قرار من رئيس مجلس الوزراء .
ولمجلس الإدارة أن يشكل من بين أعضائه لجنة أو أكثر يعهد إليها بصفة مؤقتة ببعض المهام ، وللمجلس أن يفوض رئيس مجلس الإدارة أو الرئيس التنفيذى للمركز فى بعض اختصاصاته .$m231$,'5f4630e3b49e111f96b883ed467cd656'),
(21,0,$m231$المادة 21$m231$,$m231$مجلس إدارة المركز هو السلطة المهيمنة على شئونه ومباشرة اختصاصاته ، وله أن يتخذ ما يراه لازما من قرارات لتحقيق أغراض المركز والقانون ولائحته التنفيذية وله على الأخص ما يأتى :
إقرار السياسات والخطط الاستراتيجية والبرامج اللازمة لحماية البيانات الشخصية .
اعتماد اللوائح والضوابط والتدابير والمعايير الخاصة بحماية البيانات الشخصية .
اعتماد خطط التعاون الدولى وتبادل الخبرات مع الجهات والمنظمات الدولية .
اعتماد الهيكل التنظيمى واللوائح المالية والإدارية والموارد البشرية والموازنة السنوية للمركز .
الموافقة على إنشاء ، مكاتب أو فروع للمركز على مستوى الجمهورية .
قبول المنح والتبرعات والهبات اللازمة لتحقيق أغراض المركز بعد الحصول على الموافقات المتطلبة قانونا .$m231$,'d563c43137a6ba15327a1015e3d9cd04'),
(22,0,$m231$المادة 22$m231$,$m231$يجتمع مجلس إدارة المركز بدعوة من رئيسه مرة على الأقل كل شهر ، وكلما دعت الحاجة لذلك ، ويكون اجتماعه صحيحا بحضور أغلبية أعضائه ، وتصدر قراراته بأغلبية ثلثى أصوات الأعضاء الحاضرين ، وللرئيس أن يدعو من يرى حضور الاجتماع دون أن يكون له صوت معدود .$m231$,'f8cd7d64dedf65d60975645d35305ae3'),
(23,0,$m231$المادة 23$m231$,$m231$يكون للمركز رئيس تنفيذى ، يصدر بتعيينه وتحديد معاملته المالية قرار من رئيس مجلس الوزراء بناء على اقتراح الوزير المختص لمدة أربع سنوات قابلة للتجديد لمرة واحدة .
ويكون مسئولا أمام مجلس الإدارة عن سير أعمال المركز فنيا وإداريا وماليا ، ويمثله فى صلاته بالغير وأمام القضاء وله على الأخص ما يأتى :
1 - الإشراف على تنفيذ قرارات مجلس الإدارة .
2 - إدارة المركز والإشراف على سير العمل به ، وتصريف شئونه .
3 - عرض تقارير دورية على مجلس الإدارة عن نشاط المركز وسير العمل به وما تم إنجازه وفقا للأهداف والخطط والبرامج الموضوعة ، وتحديد معوقات الأداء ، والحلول المقترحة لتفاديها .
4 - ممارسة الاختصاصات الأخرى التى تحددها لوائح المركز .
5 - اتخاذ كل ما يلزم لإنفاذ جميع مهام المركز واختصاصاته الواردة فى المادة (21) من هذا القانون .
ويعاون الرئيس التنفيذى فى مباشرة اختصاصاته عدد كاف من الخبراء والفنيين والإداريين وفقا للهيكل التنظيمى للمركز .$m231$,'34925aecacb52d64030c157d89a74ca0'),
(24,0,$m231$المادة 24$m231$,$m231$يحظر على أعضاء مجلس إدارة المركز والعاملين به ، إفشاء أى وثائق أو مستندات أو بيانات تتعلق بالحالات التى يقوم المركز برقابتها أو فحصها أو التى يتم تقديمها أو تداولها أثناء فحص أو إصدار القرارات الخاصة بها ، ويظل هذا الالتزام قائما بعد انتهاء العلاقة بالمركز .
وفى جميع الأحوال ، لا يجوز الإفصاح عن المعلومات والوثائق والمستندات والبيانات المشار إليها فى هذه المادة إلا لسلطات التحقيق والجهات والهيئات القضائية .$m231$,'c1d99e36103ec2283ef1439ade9e2c25'),
(25,0,$m231$المادة 25$m231$,$m231$للمركز بالتنسيق مع السلطات المختصة التعاون مع نظرائه بالبلاد الأجنبية وذلك فى إطار اتفاقيات التعاون الدولية والإقليمية والثنائية أو بروتوكولات التعاون المصدق عليها أو تطبيقا لمبدأ المعاملة بالمثل بما من شأنه حماية البيانات الشخصية والتحقق من مدى الامتثال للقانون من قبل المتحكمين والمعالجين خارج الجمهورية ، ويعمل المركز على تبادل البيانات والمعلومات بما من شأنه أن يكفل حماية البيانات الشخصية وعدم انتهاكها والمساعدة فى التحقيق فى الانتهاكات والجرائم ذات الصلة وتتبع مرتكبيها .$m231$,'9d3ef19423ad9b3c63d161e817af5bbc'),
(26,0,$m231$المادة 26$m231$,$m231$يصدر المركز التراخيص أو التصاريح أو الاعتمادات على النحو الآتى :
1 - يقوم المركز بتصنيف التراخيص والتصاريح والاعتمادات وتحديد أنواعها ، ووضع الشروط الخاصة بمنح كل نوع منها ، وذلك وفقا لما تحدده اللائحة التنفيذية لهذا القانون .
2 - إصدار التراخيص أو التصاريح للمتحكم أو المعالج لإجراء عمليات حفظ البيانات ، والتعامل عليها ومعالجتها وفقا لأحكام هذا القانون .
3 - إصدار التراخيص أو التصاريح الخاصة بالتسويق الإلكترونى المباشر .
4 - إصدار التراخيص أو التصاريح الخاصة بالمعالجات التى تقوم بها الجمعيات أو النقابات أو النوادى للبيانات الشخصية لأعضاء تلك الجهات وفى إطار أنشطتها .
5 - إصدار التراخيص أو التصاريح الخاصة بوسائل المراقبة البصرية فى الأماكن العامة .
6 - إصدار التراخيص أو التصاريح الخاصة بالتحكم أو معالجة البيانات الشخصية الحساسة .
7 - إصدار التصاريح والاعتمادات الخاصة بالجهات والأفراد التى تتيح لهم تقديم الاستشارات فى إجراءات حماية البيانات الشخصية ، وإجراءات الامتثال لها .
8 - إصدار التراخيص والتصاريح الخاصة بنقل البيانات الشخصية عبر الحدود .
وتحدد اللائحة التنفيذية لهذا القانون أنواع هذه التراخيص والتصاريح والاعتمادات وفئاتها ومستوياتها ، وإجراءات وشروط إصدارها وتجديدها ونماذجها المستخدمة ، وذلك بمقابل رسوم لا تتجاوز مليونى جنيه بالنسبة للترخيص ، ومبلغ لا يتجاوز خمسمائة ألف جنيه للتصريح أو الاعتماد .$m231$,'250c2a7da5c08d658ff180962c8647a2'),
(27,0,$m231$المادة 27$m231$,$m231$تقدم طلبات التراخيص والتصاريح والاعتمادات على النماذج التى يضعها المركز مشفوعة بجميع المستندات والمعلومات التى يحددها ، مع تقديم ما يثبت قدرة المتقدم المالية وقدرته على توفير وتنفيذ المتطلبات والمعايير الفنية المقررة ، ويبت فى الطلب خلال مدة لا تجاوز تسعين يوما من تاريخ استيفائه لجميع المستندات والمعلومات وإلا اعتبر الطلب مرفوضا .
ويجوز للمركز طلب بيانات أو وثائق أو مستندات أخرى للبت فى الطلب ، كما يكون له الحق فى طلب توفير ضمانات إضافية لحماية البيانات الشخصية إذا تبين عدم كفاية الحماية المبينة بالمستندات المقدمة إليه .
كما يجوز للمتحكم أو المعالج الحصول على أكثر من ترخيص أو تصريح وفقا لنوعية البيانات الشخصية المتعامل عليها .$m231$,'69a00afaa16e07cef22e8f05d5db59b6'),
(28,0,$m231$المادة 28$m231$,$m231$يجوز للمركز ، وفقا لاعتبارات المصلحة العامة ، تعديل شروط الترخيص أو التصريح بعد إصداره فى أى من الحالات الآتية :
1 - الاستجابة إلى الاتفاقيات الدولية أو الإقليمية أو القوانين الوطنية ذات الصلة .
2 - بناء على طلب المرخص له .
3 - اندماج المتحكم أو المعالج مع آخرين داخل جمهورية مصر العربية أو خارجها .
4 - إذا كان التعديل ضروريا لتحقيق أهداف هذا القانون .$m231$,'6b514e4b8ff61a9a5dd3404363a5c844'),
(29,0,$m231$المادة 29$m231$,$m231$يجوز للمركز إلغاء الترخيص أو التصريح أو الاعتماد بعد إصداره فى أى من الحالات الآتية :
1 - مخالفة شروط الترخيص أو التصريح أو الاعتماد .
2 - عدم سداد رسوم تجديد الترخيص أو التصريح أو الاعتماد .
3 - تكرار عدم الامتثال لقرارات المركز .
4 - التنازل عن الترخيص أو التصريح أو الاعتماد للغير دون موافقة المركز .
5 - صدور حكم بإفلاس المتحكم أو المعالج .$m231$,'2c96e7ad4119aabac6158a0adc212f50'),
(30,0,$m231$المادة 30$m231$,$m231$مع عدم الإخلال بأحكام المسئولية المدنية والجنائية ، يقوم الرئيس التنفيذى للمركز ، فى حال ارتكاب أى مخالفة لأحكام هذا القانون بإنذار المخالف بالتوقف عن المخالفة وإزالة أسبابها أو آثارها خلال فترة زمنية يحددها ، فإذا انقضت المدة المشار إليها دون تنفيذ مضمون ذلك الإنذار ، كان لمجلس إدارة المركز أن يصدر قرارا مسببا بما يأتى :
1 - الإنذار بإيقاف الترخيص أو التصريح أو الاعتماد جزئيا أو كليا لمدة محددة .
2 - إيقاف الترخيص أو التصريح أو الاعتماد جزئيا أو كليا .
3 - سحب الترخيص أو التصريح أو الاعتماد أو إلغاؤه جزئيا أو كليا .
4 - نشر بيان بالمخالفات التى ثبت وقوعها فى وسيلة إعلام أو أكثر واسعة الانتشار على نفقة المخالف .
5 - إخضاع المتحكم أو المعالج للإشراف الفنى للمركز لتأمين حماية البيانات الشخصية على نفقتهما بحسب الأحوال .$m231$,'77bf9e4d4b5e04b0dfc9b9d21f047eae'),
(31,0,$m231$المادة 31$m231$,$m231$يكون للمركز موازنة خاصة تعد على نمط موازنات الهيئات الاقتصادية طبقا للقواعد التى تحددها لائحة المركز وتتبع قواعد النظام المحاسبى الموحد ، وذلك دون التقيد بالقواعد والنظم الحكومية ، وتبدأ السنة المالية للمركز مع بداية السنة المالية للدولة وتنتهى بنهايتها ، كما يكون للمركز حساب خاص لدى البنك المركزى تودع فيه موارده ، ويجوز له إنشاء حساب باسمه لدى أحد البنوك التجارية بعد موافقة وزير المالية ، ويرحل الفائض من موازنة المركز من سنة مالية إلى أخرى ، ويتم الصرف من موارده وفقا للائحته المالية وذلك فى المجالات التى يحددها مجلس إدارته ، وتتكون موارده من الآتى :
1 - ما يخصص له من موازنة هيئة تنمية صناعة تكنولوجيا المعلومات .
2 - ما يخصص له من الخزانة العامة بما لا يقل عن ثلث حصيلة الغرامات المقضى بها تطبيقا لأحكام هذا القانون .
3 - مقابل الخدمات التى يقوم المركز بتقديمها .
4 - قيمة رسوم ومقابل التراخيص والتصاريح والاعتمادات التى يتم إصدارها وقيمة التصالحات التى يتم قبولها .
5 - عائد استثمار أموال المركز .
6 - ما يقبله مجلس الإدارة من المنح والتبرعات والهبات .$m231$,'fc1836ed384b7e29d7889ae79f83cb8a'),
(32,0,$m231$المادة 32$m231$,$m231$يجوز للشخص المعنى بالبيانات ولكل ذى صفة أن يتقدم إلى أى حائز أو متحكم أو معالج بطلب يتعلق بممارسة حقوقه المنصوص عليها فى هذا القانون ، ويلتزم المقدم إليه الطلب بالرد عليه خلال ستة أيام عمل من تاريخ تقديمه إليه .$m231$,'6d72f1d0d866858e36cbeb23d7b80db1'),
(33,0,$m231$المادة 33$m231$,$m231$مع عدم الإخلال بالحق فى اللجوء إلى القضاء ، يكون للشخص المعنى بالبيانات ولكل ذى صفة ومصلحة مباشرة حق الشكوى فى الحالات الآتية :
1 - انتهاك حق حماية البيانات الشخصية أو الإخلال به .
2 - الامتناع عن تمكين الشخص المعنى بالبيانات من استيفاء حقوقه .
3 - القرارات الصادرة عن المسئول عن حماية البيانات الشخصية لدى المعالج أو المتحكم بشأن الطلبات المقدمة إليه .
وتقدم الشكوى إلى المركز ، وله فى ذلك اتخاذ ما يلزم من إجراءات التحقيق ، وعليه أن يصدر قراره خلال ثلاثين يوم عمل من تاريخ تقديمها إليه ، على أن يخطر الشاكى والمشكو فى حقه بالقرار .
ويلتزم المشكو فى حقه بتنفيذ قرار المركز خلال سبعة أيام عمل من تاريخ إخطاره به ، وإفادة المركز بما تم نحو تنفيذه .$m231$,'583829804a0294a239de700c0a5ae289'),
(34,0,$m231$المادة 34$m231$,$m231$يكون للعاملين بالمركز الذين يصدر بتحديدهم قرار من وزير العدل بناء على اقتراح الوزير المختص صفة الضبطية القضائية فى إثبات الجرائم التى تقع بالمخالفة لأحكام هذا القانون .$m231$,'d8fae169bb2108d869054831cf013d7f'),
(35,0,$m231$المادة 35$m231$,$m231$مع عدم الإخلال بأى عقوبة أشد منصوص عليها فى أى قانون آخر ، ومع عدم الإخلال بحق المضرور فى التعويض ، يعاقب على الجرائم المنصوص عليها فى المواد التالية بالعقوبات المقررة لها .$m231$,'0f228e18148298dc512e077532a05129'),
(36,0,$m231$المادة 36$m231$,$m231$يعاقب بغرامة لا تقل عن مائة ألف جنيه ولا تجاوز مليون جنيه كل حائز أو متحكم أو معالج جمع أو عالج أو أفشى أو أتاح أو تداول بيانات شخصية معالجة إلكترونيا بأى وسيلة من الوسائل فى غير الأحوال المصرح بها قانونا أو بدون موافقة الشخص المعنى بالبيانات .
وتكون العقوبة الحبس مدة لا تقل عن ستة شهور وبغرامة لا تقل عن مائتى ألف جنيه ولا تجاوز مليونى جنيه ، أو بإحدى هاتين العقوبتين ، إذا ارتكب ذلك مقابل الحصول على منفعة مادية أو أدبية ، أو بقصد تعريض الشخص المعنى بالبيانات للخطر أو الضرر .$m231$,'c6a4fec5d60a8734125c3e4a6c376dee'),
(37,0,$m231$المادة 37$m231$,$m231$يعاقب بغرامة لا تقل عن مائة ألف جنيه ولا تجاوز مليون جنيه ، كل حائز أو متحكم أو معالج امتنع دون مقتض من القانون عن تمكين الشخص المعنى بالبيانات من ممارسة حقوقه المنصوص عليها فى المادة (2) من هذا القانون ويعاقب بغرامة لا تقل عن مائتى ألف جنيه ولا تجاوز مليونى جنيه كل من جمع بيانات شخصية بدون توافر الشروط المنصوص عليها فى المادة (3) من هذا القانون .$m231$,'05cc0bd241226972665127ec13795f0f'),
(38,0,$m231$المادة 38$m231$,$m231$يعاقب بغرامة لا تقل عن ثلاثمائة ألف جنيه ولا تجاوز ثلاثة ملايين جنيه ، كل متحكم أو معالج لم يلتزم بواجباته المنصوص عليها فى المواد (4 ، 5 ، 7) من هذا القانون .$m231$,'57573a4d4c3c790725dd89ee6a8eb44c'),
(39,0,$m231$المادة 39$m231$,$m231$يعاقب بالغرامة التى لا تقل عن مائتى ألف جنيه ولا تجاوز مليونى جنيه ، كل ممثل قانونى للشخص الاعتبارى لم يلتزم بأحد واجباته المنصوص عليها فى المادة (8) من هذا القانون .$m231$,'4ff6e95648872cc5ee68c9d03dc534ad'),
(40,0,$m231$المادة 40$m231$,$m231$يعاقب بغرامة لا تقل عن مائتى ألف جنيه ولا تجاوز مليونى جنيه ، كل مسئول حماية بيانات شخصية لم يلتزم بمقتضيات وظيفته المنصوص عليها فى المادة (9) من هذا القانون .
ويعاقب بغرامة لا تقل عن خمسين ألف جنيه ولا تجاوز خمسمائة ألف جنيه إذا وقعت الجريمة نتيجة لإهمال مسئول حماية البيانات الشخصية .$m231$,'f22f495c89938b38dce858bd17a971be'),
(41,0,$m231$المادة 41$m231$,$m231$يعاقب بالحبس مدة لا تقل عن ثلاثة شهور وبغرامة لا تقل عن خمسمائة ألف جنيه ولا تجاوز خمسة ملايين جنيه ، أو بإحدى هاتين العقوبتين ، كل حائز أو متحكم أو معالج جمع أو أتاح أو تداول أو عالج أو أفشى أو خزن أو نقل أو حفظ بيانات شخصية حساسة بدون موافقة الشخص المعنى بالبيانات أو فى غير الأحوال المصرح بها قانونا .$m231$,'1bdff2f295f3cabcacfd0f4b128ddc62'),
(42,0,$m231$المادة 42$m231$,$m231$يعاقب بالحبس مدة لا تقل عن ثلاثة شهور وبغرامة لا تقل عن خمسمائة ألف جنيه ولا تجاوز خمسة ملايين جنيه ، أو بإحدى هاتين العقوبتين ، كل من خالف أحكام حركة البيانات الشخصية عبر الحدود المنصوص عليها فى المواد (14 ، 15 ، 16) من هذا القانون .$m231$,'f9522190f1d1897e7157a69ee655718b'),
(43,0,$m231$المادة 43$m231$,$m231$يعاقب بغرامة لا تقل عن مائتى ألف جنيه ولا تجاوز مليونى جنيه ، كل من خالف أحكام التسويق الإلكترونى المنصوص عليها فى المادتين (17 ، 18) من هذا القانون .$m231$,'f1b26592717bc40930de12a8eed8fcfd'),
(44,0,$m231$المادة 44$m231$,$m231$يعاقب بغرامة لا تقل عن ثلاثمائة ألف جنيه ولا تجاوز ثلاثة ملايين جنيه ، كل عضو مجلس إدارة أو أى من العاملين بالمركز خالف الالتزامات المنصوص عليها فى المادة (24) من هذا القانون .$m231$,'67af7c8a2a7ed4422b25fd80c14903a0'),
(45,0,$m231$المادة 45$m231$,$m231$يعاقب بغرامة لا تقل عن خمسمائة ألف جنيه ولا تجاوز خمسة ملايين جنيه ، كل من خالف أحكام التراخيص أو التصاريح أو الاعتمادات المنصوص عليها فى هذا القانون .$m231$,'691492c98d64f34deacf75008adfb3a8'),
(46,0,$m231$المادة 46$m231$,$m231$يعاقب بالحبس مدة لا تقل عن ستة أشهر وبغرامة لا تقل عن مائتى ألف جنيه ولا تجاوز مليونى جنيه ، أو بإحدى هاتين العقوبتين ، كل من منع أحد العاملين بالمركز ممن يتمتعون بصفة الضبطية القضائية من أداء عمله .$m231$,'71cfdbc500b1a5ee2f507babbdd2f640'),
(47,0,$m231$المادة 47$m231$,$m231$يعاقب المسئول عن الإدارة الفعلية للشخص الاعتبارى المخالف بذات العقوبات المقررة عن الأفعال التى ترتكب بالمخالفة لأحكام هذا القانون ، إذا ثبت علمه بها ، وكان إخلاله بالواجبات التى تفرضها عليه تلك الإدارة قد أسهم فى وقوع الجريمة .
ويكون الشخص الاعتبارى مسئولا بالتضامن عن الوفاء بما يحكم به من تعويضات إذا كانت المخالفة قد ارتكبت من أحد العاملين لديه وباسم الشخص الاعتبارى ولصالحه .$m231$,'71fe848da7e81a4d20b980f0a2d67574'),
(48,0,$m231$المادة 48$m231$,$m231$فى جميع الأحوال ، وفضلا عن العقوبات المنصوص عليها فى هذا القانون ، تقضى المحكمة بنشر حكم الإدانة فى جريدتين واسعتى الانتشار ، وعلى شبكات المعلومات الإلكترونية المفتوحة على نفقة المحكوم عليه .
وفى حالة العود ، تضاعف العقوبات الواردة فى هذا الفصل بحديها الأقصى والأدنى .
ويعاقب على الشروع فى ارتكاب الجرائم المنصوص عليها فى هذا القانون بنصف العقوبة المقررة لها .$m231$,'2a1a1d1986feb68ccef41740dbae99e9'),
(49,0,$m231$المادة 49$m231$,$m231$يجوز للمتهم فى أى حالة كانت عليها الدعوى الجنائية ، وقبل صيرورة الحكم باتا ، إثبات الصلح مع المجنى عليه أو وكيله الخاص أو خلفه العام ، وبموافقة المركز أمام النيابة العامة أو المحكمة المختصة بحسب الأحوال ، وذلك فى الجنح المنصوص عليها فى المواد (36 ، 37 ، 38 ، 39 ، 40 ، 41 ، 43) من هذا القانون .
ويكون التصالح مع المركز فى الجنح المنصوص عليها بالمواد (42 ، 44 ، 45) من هذا القانون فى أى حالة كانت عليها الدعوى .
وفى جميع الأحوال ، يجب على المتهم الذى يرغب فى التصالح أن يسدد قبل رفع الدعوى الجنائية مبلغا يعادل نصف الحد الأدنى للغرامة المقررة للجريمة .
ويسدد المتهم راغب التصالح بعد رفع الدعوى وقبل صيرورة الحكم باتا نصف الحد الأقصى للغرامة المقررة للجريمة ، أو قيمة الغرامة المقضى بها أيهما أكبر .
ويكون السداد فى خزانة المحكمة المختصة أو النيابة العامة أو المركز بحسب الأحوال .
ويترتب على التصالح انقضاء الدعوى الجنائية دون أن يكون له أثر على حقوق المضرور من الجريمة .$m231$,'6e6b1838bdfdf0659d181ad2d64fd3bb');

INSERT INTO m231_ver VALUES
(0,0,1,$m231$قانون رقم 151 لسنة 2020 بإصدار قانون حماية البيانات الشخصية
رئيس الجمهورية
باسم الشعب
رئيس الجمهورية
قرر مجلس النواب القانون الآتى نصه ، وقد أصدرناه :$m231$,'8d618864b487639c30407cc3615f7a70',DATE '2020-07-13',NULL,'active',NULL,NULL,NULL),
(1,-1,1,$m231$يعمل بأحكام هذا القانون والقانون المرافق فى شأن حماية البيانات الشخصية المعالجة إلكترونيا جزئيا أو كليا لدى أى حائز أو متحكم أو معالج لها ، وذلك بالنسبة للأشخاص الطبيعيين .$m231$,'815f2ff5dcd83bb6f4ba14bb26efc008',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(2,-1,1,$m231$تسرى أحكام هذا القانون والقانون المرافق له على كل من ارتكب إحدى الجرائم المنصوص عليها فى القانون المرافق متى كان الجانى من المصريين داخل الجمهورية أو خارجها ، أو كان من غير المصريين المقيمين داخل الجمهورية ، أو كان من غير المصريين خارج الجمهورية إذا كان الفعل معاقبا عليه فى الدولة التى وقع فيها تحت أى وصف قانونى وكانت البيانات محل الجريمة لمصريين أو أجانب مقيمين داخل الجمهورية .$m231$,'0d52eefc232a178e53b0417905b1fdad',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(3,-1,1,$m231$لا تسرى أحكام القانون المرافق على ما يأتى :
1 - البيانات الشخصية التى يحتفظ بها الأشخاص الطبيعيون للغير ، ويتم معالجتها للاستخدام الشخصى .
2 - البيانات الشخصية التى تتم معالجتها بغرض الحصول على البيانات الإحصائية الرسمية أو تطبيقا لنص قانونى .
3 - البيانات الشخصية التى تتم معالجتها حصرا للأغراض الإعلامية بشرط أن تكون صحيحة ودقيقة ، وألا تستخدم فى أى أغراض أخرى ، وذلك دون الإخلال بالتشريعات المنظمة للصحافة والإعلام .
4 - البيانات الشخصية المتعلقة بمحاضر الضبط القضائى والتحقيقات والدعاوى القضائية .
5 - البيانات الشخصية لدى جهات الأمن القومى ، وما تقدره لاعتبارات أخرى .
ويجب على المركز ، بناء على طلب جهات الأمن القومى ، إخطار المتحكم أو المعالج بتعديل أو محو أو عدم إظهار أو إتاحة أو تداول البيانات الشخصية ، خلال مدة زمنية محددة ، وفقا لاعتبارات الأمن القومى ، ويلتزم المتحكم أو المعالج بتنفيذ ما ورد بالإخطار خلال المدة الزمنية المحددة به .
6 - البيانات الشخصية لدى البنك المركزى المصرى والجهات الخاضعة لرقابته وإشرافه ، عدا شركات تحويل الأموال وشركات الصرافة ، على أن يراعى فى شأنهما القواعد المقررة من البنك المركزى المصرى بشأن التعامل مع البيانات الشخصية .$m231$,'c8c5a179d1478887264c71b860bd6e39',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(4,-1,1,$m231$يصدر الوزير المعنى بشئون الاتصالات وتكنولوجيا المعلومات اللائحة التنفيذية للقانون المرافق خلال ستة أشهر من تاريخ العمل بهذا القانون .$m231$,'b1c7b5deb016263c4c6a58f51465dced',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(5,-1,1,$m231$تختص المحاكم الاقتصادية بنظر الجرائم التى ترتكب بالمخالفة لأحكام القانون المرافق .$m231$,'d38418ec354eeba990df3fde028b91f7',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(6,-1,1,$m231$يلتزم المخاطبون بأحكام هذا القانون بتوفيق أوضاعهم طبقا لأحكام القانون المرافق ولائحته التنفيذية ، وذلك خلال سنة من تاريخ صدور هذه اللائحة .$m231$,'42a42b1c9f3b306f67b8f43f75e43e2d',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(7,-1,1,$m231$ينشر هذا القانون فى الجريدة الرسمية ، ويعمل به بعد مضى ثلاثة أشهر من اليوم التالى لتاريخ نشره .
يبصم هذا القانون بخاتم الدولة ، وينفذ كقانون من قوانينها .
صدر برئاسة الجمهورية فى 22 ذى القعدة سنة 1441 هـ
( الموافق 13 يوليو سنة 2020 م ) .
عبد الفتاح السيسى$m231$,'fea5af411eaaf6eeca5ebb56f5912be2',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(1,0,1,$m231$فى تطبيق أحكام هذا القانون ، يقصد بالكلمات والعبارات التالية المعنى المبين قرين كل منها :
البيانات الشخصية : أى بيانات متعلقة بشخص طبيعى محدد ، أو يمكن تحديده بشكل مباشر أو غير مباشر عن طريق الربط بين هذه البيانات وأى بيانات أخرى كالاسم ، أو الصوت ، أو الصورة ، أو رقم تعريفى ، أو محدد للهوية عبر الإنترنت ، أو أى بيانات تحدد الهوية النفسية ، أو الصحية ، أو الاقتصادية ، أو الثقافية ، أو الاجتماعية .
المعالجة : أى عملية إلكترونية أو تقنية لكتابة البيانات الشخصية ، أو تجميعها ، أو تسجيلها ، أو حفظها ، أو تخزينها ، أو دمجها ، أو عرضها ، أو إرسالها ، أو استقبالها ، أو تداولها ، أو نشرها ، أو محوها ، أو تغييرها ، أو تعديلها ، أو استرجاعها أو تحليلها وذلك باستخدام أى وسيط من الوسائط أو الأجهزة الإلكترونية أو التقنية سواء تم ذلك جزئيا أو كليا .
البيانات الشخصية الحساسة : البيانات التى تفصح عن الصحة النفسية أو العقلية أو البدنية أو الجينية ، أو بيانات القياسات الحيوية "البيومترية" أو البيانات المالية أو المعتقدات الدينية أو الآراء السياسية أو الحالة الأمنية ، وفى جميع الأحوال تعد بيانات الأطفال من البيانات الشخصية الحساسة .
الشخص المعنى بالبيانات : أى شخص طبيعى تنسب إليه بيانات شخصية معالجة إلكترونيا تدل عليه قانونا أو فعلا ، وتمكن من تمييزه عن غيره .
الحائز : أى شخص طبيعى أو اعتبارى ، يحوز ويحتفظ قانونيا أو فعليا ببيانات شخصية فى أى صورة ، أو على أى وسيلة تخزين سواء أكان هو المنشئ للبيانات ، أم انتقلت إليه حيازتها بأى صورة .
المتحكم : أى شخص طبيعى أو اعتبارى يكون له بحكم أو طبيعة عمله ، الحق فى الحصول على البيانات الشخصية وتحديد طريقة وأسلوب ومعايير الاحتفاظ بها ، أو معالجتها والتحكم فيها طبقا للغرض المحدد أو نشاطه .
المعالج : أى شخص طبيعى أو اعتبارى مختص بطبيعة عمله ، بمعالجة البيانات الشخصية لصالحه أو لصالح المتحكم بالاتفاق معه ووفقا لتعليماته .
إتاحة البيانات الشخصية : كل وسيلة تحقق اتصال علم الغير بالبيانات الشخصية كالاطلاع أو التداول أو النشر أو النقل أو الاستخدام أو العرض أو الإرسال أو الاستقبال أو الإفصاح عنها .
أمن البيانات : إجراءات وعمليات تقنية وتنظيمية من شأنها الحفاظ على خصوصية البيانات الشخصية وسريتها وسلامتها ووحدتها وتكاملها فيما بينها .
خرق وانتهاك البيانات الشخصية : كل دخول غير مرخص به إلى بيانات شخصية أو وصول غير مشروع لها ، أو أى عملية غير مشروعة لنسخ أو إرسال أو توزيع أو تبادل أو نقل أو تداول يهدف إلى الكشف أو الإفصاح عن البيانات الشخصية أو إتلافها أو تعديلها أثناء تخزينها أو نقلها أو معالجتها .
حركة البيانات الشخصية عبر الحدود : نقل البيانات أو إتاحتها أو تسجيلها أو تخزينها أو تداولها أو نشرها أو استخدامها أو عرضها أو إرسالها أو استقبالها أو استرجاعها أو معالجتها ، من داخل النطاق الجغرافى لجمهورية مصر العربية إلى خارجه أو العكس .
التسويق الإلكترونى : إرسال أى رسالة أو بيان أو محتوى إعلانى أو تسويقى بأى وسيلة تقنية أيا كانت طبيعتها أو صورتها تستهدف بشكل مباشر أو غير مباشر ترويج سلع أو خدمات أو التماسات أو طلبات تجارية أو سياسية أو اجتماعية أو خيرية موجهة إلى أشخاص بعينهم .
جهات الأمن القومى : رئاسة الجمهورية ووزارة الدفاع ووزارة الداخلية وجهاز المخابرات العامة وهيئة الرقابة الإدارية .
المركز : مركز حماية البيانات الشخصية .
الترخيص : وثيقة رسمية تصدر عن المركز للشخص الاعتبارى تمنحه من خلالها الحق فى مزاولة نشاط جمع البيانات الشخصية الإلكترونية أو تلقيها أو نقلها أو تخزينها أو معالجتها أو القيام بأنشطة التسويق الإلكترونى أو كل ما سبق والتعامل عليها بأى صورة ، وتحدد التزامات المرخص له وفق القواعد والشروط والإجراءات والمعايير الفنية المحددة باللائحة التنفيذية لهذا القانون ، وذلك لمدة ثلاث سنوات قابلة للتجديد لمدد أخرى .
التصريح : وثيقة رسمية تصدر عن المركز للشخص الطبيعى أو الاعتبارى تمنحه من خلالها الحق فى ممارسة نشاط جمع البيانات الشخصية الإلكترونية أو تخزينها أو نقلها أو معالجتها أو القيام بأنشطة التسويق الإلكترونى أو كل ما سبق والتعامل عليها بأى صورة ، أو لأداء مهمة أو مهام معينة ، وتحدد هذه الوثيقة التزامات المصرح له وفق القواعد والشروط والإجراءات والمعايير الفنية المحددة باللائحة التنفيذية ، لمدة مؤقتة لا تجاوز سنة ، ويجوز تجديدها لأكثر من مدة .
الاعتماد : شهادة تصدر عن المركز تفيد أن الشخص الطبيعى أو الاعتبارى قد استوفى جميع المتطلبات الفنية والقانونية والتنظيمية المحددة باللائحة التنفيذية لهذا القانون ويكون بموجبها مؤهلا لتقديم الاستشارات فى مجال حماية البيانات الشخصية .
الوزير المختص : الوزير المعنى بشئون الاتصالات وتكنولوجيا المعلومات .$m231$,'e2799b77b7bbf86a5b37406cf6becd92',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(2,0,1,$m231$لا يجوز جمع البيانات الشخصية أو معالجتها أو الإفصاح عنها أو إفشائها بأى وسيلة من الوسائل إلا بموافقة صريحة من الشخص المعنى بالبيانات ، أو فى الأحوال المصرح بها قانونا .
ويكون للشخص المعنى بالبيانات الحقوق الآتية :
1 - العلم بالبيانات الشخصية الخاصة به الموجودة لدى أى حائز أو متحكم أو معالج والاطلاع عليها والوصول إليها أو الحصول عليها .
2 - العدول عن الموافقة المسبقة على الاحتفاظ ببياناته الشخصية أو معالجتها .
3 - التصحيح أو التعديل أو المحو أو الإضافة أو التحديث للبيانات الشخصية .
4 - تخصيص المعالجة فى نطاق محدد .
5 - العلم والمعرفة بأى خرق أو انتهاك لبياناته الشخصية .
6 - الاعتراض على معالجة البيانات الشخصية أو نتائجها متى تعارضت مع الحقوق والحريات الأساسية للشخص المعنى بالبيانات .
وباستثناء البند (5) من الفقرة السابقة ، يؤدى الشخص المعنى بالبيانات مقابل تكلفة الخدمة المقدمة إليه من المتحكم أو المعالج فيما يخص ممارسته لحقوقه ، ويتولى المركز إصدار قرارات تحديد هذا المقابل بما لا يجاوز عشرين ألف جنيه .$m231$,'bac52e4d9b1a41aa9ffdc50a331937c0',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(3,0,1,$m231$يجب لجمع البيانات الشخصية ومعالجتها والاحتفاظ بها ، توافر الشروط الآتية :
1 - أن تجمع البيانات الشخصية لأغراض مشروعة ومحددة ومعلنة للشخص المعنى .
2 - أن تكون صحيحة وسليمة ومؤمنة .
3 - أن تعالج بطريقة مشروعة وملائمة للأغراض التى تم تجميعها من أجلها .
4 - ألا يتم الاحتفاظ بها لمدة أطول من المدة اللازمة للوفاء بالغرض المحدد لها .
وتحدد اللائحة التنفيذية لهذا القانون السياسات والإجراءات والضوابط والمعايير القياسية للجمع والمعالجة والحفظ والتأمين لهذه البيانات .$m231$,'60ed3108b1732310ef02958adc585d10',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(4,0,1,$m231$مع مراعاة أحكام المادة (12) من هذا القانون ، يلتزم المتحكم بما يأتى :
1 - الحصول على البيانات الشخصية أو تلقيها من الحائز أو من الجهات المختصة بتزويده بها بحسب الأحوال بعد موافقة الشخص المعنى بالبيانات ، أو فى الأحوال المصرح بها قانونا .
2 - التأكد من صحة البيانات الشخصية واتفاقها وكفايتها مع الغرض المحدد لجمعها .
3 - وضع طريقة وأسلوب ومعايير المعالجة طبقا للغرض المحدد ، ما لم يقرر تفويض المعالج فى ذلك بموجب تعاقد مكتوب .
4 - التأكد من انطباق الغرض المحدد من جمع البيانات الشخصية لأغراض معالجتها .
5 - القيام بعمل أو الامتناع عن عمل يكون من شأنه إتاحة البيانات الشخصية إلا فى الأحوال المصرح بها قانونا .
6 - اتخاذ جميع الإجراءات التقنية والتنظيمية وتطبيق المعايير القياسية اللازمة لحماية البيانات الشخصية وتأمينها حفاظا على سريتها ، وعدم اختراقها أو إتلافها أو تغييرها أو العبث بها قبل أى إجراء غير مشروع .
7 - محو البيانات الشخصية لديه فور انقضاء الغرض المحدد منها ، أما فى حال الاحتفاظ بها لأى سبب من الأسباب المشروعة بعد انتهاء الغرض ، فيجب ألا تبقى فى صورة تسمح بتحديد الشخص المعنى بالبيانات .
8 - تصحيح أى خطأ بالبيانات الشخصية فور إبلاغه أو علمه به .
9 - إمساك سجل خاص للبيانات ، على أن يتضمن وصف فئات البيانات الشخصية لديه ، وتحديد من سيفصح لهم عن هذه البيانات أو يتيحها لهم وسنده والمدد الزمنية وقيودها ونطاقها وآليات محو البيانات الشخصية لديه أو تعديلها وأى بيانات أخرى متعلقة بنقل تلك البيانات الشخصية عبر الحدود ووصف الإجراءات التقنية والتنظيمية الخاصة بأمن البيانات .
10 - الحصول على ترخيص أو تصريح من المركز للتعامل مع البيانات الشخصية .
11 - يلتزم المتحكم خارج جمهورية مصر العربية بتعيين ممثل له فى جمهورية مصر العربية وذلك على النحو الذى تبينه اللائحة التنفيذية .
12 - توفير الإمكانيات اللازمة لإثبات التزامه بتطبيق أحكام هذا القانون وتمكين المركز من التفتيش والرقابة للتأكد من ذلك .
وفى حال وجود أكثر من متحكم يلتزم كل منهم بجميع الالتزامات المنصوص عليها فى هذا القانون ، وللشخص المعنى ممارسة حقوقه تجاه كل متحكم على حدة .
وتحدد اللائحة التنفيذية لهذا القانون السياسات والإجراءات والضوابط والمعايير الفنية لتلك الالتزامات .$m231$,'4d70bd6698f6b5c1e69a8e6ba1a80b84',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(5,0,1,$m231$مع مراعاة أحكام المادة (12) من هذا القانون ، يلتزم معالج البيانات الشخصية بما يأتى :
1 - إجراء المعالجة وتنفيذها طبقا للقواعد المنظمة لذلك بهذا القانون ولائحته التنفيذية ووفقا للحالات المشروعة والقانونية وبناء على التعليمات المكتوبة الواردة إليه من المركز أو المتحكم أو من أى ذى صفة بحسب الأحوال ، وبصفة خاصة فيما يتعلق بنطاق عملية المعالجة وموضوعها وطبيعتها ونوع البيانات الشخصية واتفاقها وكفايتها مع الغرض المحدد له .
2 - أن تكون أغراض المعالجة وممارستها مشروعة ، ولا تخالف النظام العام أو الآداب العامة .
3 - عدم تجاوز الغرض المحدد للمعالجة ومدتها ، ويجب إخطار المتحكم أو الشخص المعنى بالبيانات أو كل ذى صفة ، بحسب الأحوال ، بالمدة اللازمة للمعالجة .
4 - محو البيانات الشخصية بانقضاء مدة المعالجة أو تسليمها للمتحكم .
5 - القيام بعمل أو الامتناع عن عمل يكون من شأنه إتاحة البيانات الشخصية أو نتائج المعالجة إلا فى الأحوال المصرح بها قانونا .
6 - عدم إجراء أى معالجة للبيانات الشخصية تتعارض مع غرض المتحكم فيها أو نشاطه إلا إذا كان ذلك بغرض إحصائى أو تعليمى ولا يهدف للربح ودون الإخلال بحرمة الحياة الخاصة .
7 - حماية وتأمين عملية المعالجة والوسائط والأجهزة الإلكترونية المستخدمة فى ذلك وما عليها من بيانات شخصية .
8 - عدم إلحاق أى ضرر بالشخص المعنى بالبيانات بشكل مباشر أو غير مباشر .
9 - إعداد سجل خاص بعمليات المعالجة لديه ، على أن يتضمن فئات المعالجة التى يجريها نيابة عن أى متحكم وبيانات الاتصال به ومسئول حماية البيانات لديه ، والمدد الزمنية للمعالجة وقيودها ونطاقها وآليات محو البيانات الشخصية لديه أو تعديلها ، ووصفا للإجراءات التقنية والتنظيمية الخاصة بأمن البيانات وعمليات المعالجة .
10 - توفير الإمكانيات لإثبات التزامه بتطبيق أحكام هذا القانون عند طلب المتحكم وتمكين المركز من التفتيش والرقابة للتأكد من التزامه بذلك .
11 - الحصول على ترخيص أو تصريح من المركز للتعامل على البيانات الشخصية .
12 - يلتزم المعالج خارج جمهورية مصر العربية بتعيين ممثل له فى جمهورية مصر العربية وذلك على النحو الذى تبينه اللائحة التنفيذية .
وفى حال وجود أكثر من معالج ، يلتزم كل منهم بجميع الالتزامات المنصوص عليها فى هذا القانون وذلك فى حال عدم وجود عقد يحدد التزامات ومسئوليات كل منهم بوضوح .
وتحدد اللائحة التنفيذية لهذا القانون السياسات والإجراءات والضوابط والشروط والتعليمات والمعايير القياسية لتلك الالتزامات .$m231$,'23b47e74464cece815e8fae0df588224',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(6,0,1,$m231$تعد المعالجة الإلكترونية مشروعة وقانونية فى حال توفر أى من الحالات الآتية :
1 - موافقة الشخص المعنى بالبيانات على إجراء المعالجة من أجل تحقيق غرض محدد أو أكثر .
2 - أن تكون المعالجة لازمة وضرورية تنفيذا لالتزام تعاقدى أو تصرف قانونى أو لإبرام عقد لصالح الشخص المعنى بالبيانات ، أو لمباشرة أى من إجراءات المطالبة بالحقوق القانونية له أو الدفاع عنها .
3 - تنفيذ التزام ينظمه القانون أو أمر من جهات التحقيق المختصة أو بناء على حكم قضائى .
4 - تمكين المتحكم من القيام بالتزاماته أو أى ذى صفة من ممارسة حقوقه المشروعة ، ما لم يتعارض ذلك مع الحقوق والحريات الأساسية للشخص المعنى بالبيانات .$m231$,'d36058eb780ccbb56291bf505dbb21f7',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(7,0,1,$m231$يلتزم كل من المتحكم والمعالج بحسب الأحوال حال علمه بوجود خرق أو انتهاك للبيانات الشخصية لديه بإبلاغ المركز خلال اثنتين وسبعين ساعة ، وفى حال كان هذا الخرق أو الانتهاك متعلقا باعتبارات حماية الأمن القومى فيكون الإبلاغ فوريا ، وعلى المركز وفى جميع الأحوال إخطار جهات الأمن القومى بالواقعة فورا ، كما يلتزم بموافاة المركز خلال اثنتين وسبعين ساعة من تاريخ علمه بما يأتى :
1 - وصف طبيعة الخرق أو الانتهاك ، وصورته وأسبابه والعدد التقريبى للبيانات الشخصية وسجلاتها .
2 - بيانات مسئول حماية البيانات الشخصية لديه .
3 - الآثار المحتملة لحادث الخرق أو الانتهاك .
4 - وصف الإجراءات المتخذة والمقترح تنفيذها لمواجهة هذا الخرق أو الانتهاك والتقليل من آثاره السلبية .
5 - توثيق أى خرق أو انتهاك للبيانات الشخصية ، والإجراءات التصحيحية المتخذة لمواجهته .
6 - أى وثائق أو معلومات أو بيانات يطلبها المركز .
وفى جميع الأحوال يجب على المتحكم والمعالج ، بحسب الأحوال ، إخطار الشخص المعنى بالبيانات خلال ثلاثة أيام عمل من تاريخ الإبلاغ وما تم اتخاذه من إجراءات .
وتحدد اللائحة التنفيذية لهذا القانون الإجراءات الخاصة بالإبلاغ والإخطار .$m231$,'ddca616decc2f0f04b839de6af409d97',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(8,0,1,$m231$ينشأ بالمركز سجل لقيد مسئولى حماية البيانات الشخصية ، وتحدد اللائحة التنفيذية لهذا القانون شروط القيد وإجراءاته وآليات التسجيل .
ويلتزم الممثل القانونى للشخص الاعتبارى لأى متحكم أو معالج بأن يعين داخل كيانه القانونى وهيكله الوظيفى موظفا مختصا مسئولا عن حماية البيانات الشخصية ، وذلك بقيده فى سجل مسئولى حماية البيانات الشخصية بالمركز ، ويعلن عن ذلك .
ويكون الشخص الطبيعى المتحكم أو المعالج هو المسئول عن تطبيق أحكام هذا القانون .$m231$,'90a4c4f559da8de8d997eab08af995ae',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(9,0,1,$m231$يكون مسئول حماية البيانات الشخصية مسئولا عن تنفيذ أحكام القانون ولائحته التنفيذية وقرارات المركز ، ومراقبة الإجراءات المعمول بها داخل كيانه والإشراف عليها ، وتلقى الطلبات المتعلقة بالبيانات الشخصية وفقا لأحكام هذا القانون .
ويلتزم على الأخص بالآتى :
1 - إجراء التقييم والفحص الدورى لنظم حماية البيانات الشخصية ومنع اختراقها ، وتوثيق نتائج التقييم وإصدار التوصيات اللازمة لحمايتها .
2 - العمل كنقطة اتصال مباشرة مع المركز وتنفيذ قراراته ، فيما يخص تطبيق أحكام هذا القانون .
3 - تمكين الشخص المعنى بالبيانات من ممارسة حقوقه المنصوص عليها فى هذا القانون .
4 - إخطار المركز فى حال وجود أى خرق أو انتهاك للبيانات الشخصية لديه .
5 - الرد على الطلبات المقدمة من الشخص المعنى بالبيانات أو كل ذى صفة ، والرد على المركز فى التظلمات المقدمة إليه من أى منهما وفقا لأحكام هذا القانون .
6 - متابعة القيد والتحديث لسجل البيانات الشخصية لدى المتحكم أو سجل عمليات المعالجة لدى المعالج ، بما يكفل ضمان دقة البيانات والمعلومات المقيدة به .
7 - إزالة أى مخالفات متعلقة بالبيانات الشخصية داخل كيانه ، واتخاذ الإجراءات التصحيحية حيالها .
8 - تنظيم البرامج التدريبية اللازمة لموظفى كيانه ، لتأهيلهم بما يتناسب مع متطلبات هذا القانون .
وتحدد اللائحة التنفيذية لهذا القانون الالتزامات والإجراءات والمهام الأخرى التى يجب على مسئول حماية البيانات الشخصية القيام بها .$m231$,'748bac8af6259a2685bf65e12ca3e882',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(10,0,1,$m231$يلتزم كل من المتحكم والمعالج والحائز عند طلب إتاحة البيانات الشخصية بالإجراءات الآتية :
1 - أن يكون بناء على طلب كتابى يقدم إليه من ذى صفة أو وفقا لسند قانونى .
2 - التحقق من توافر المستندات اللازمة لتنفيذ الإتاحة والاحتفاظ بها .
3 - البت فى الطلب ومستنداته خلال ستة أيام عمل من تاريخ تقديمه إليه ، وعند صدور قرار بالرفض يجب أن يكون الرفض مسببا ، ويعتبر مضى المدة المشار إليها دون رد فى حكم الرفض .$m231$,'9d5dfefc8231b7d4a4ff388809f6f8f1',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(11,0,1,$m231$يكون للدليل الرقمى المستمد من البيانات الشخصية طبقا لأحكام هذا القانون ذات الحجية فى الإثبات المقررة للأدلة المستمدة من البيانات والمعلومات الخطية متى استوفت المعايير والشروط الفنية الواردة باللائحة التنفيذية لهذا القانون .$m231$,'661e019d7016fc449517ef92f4932444',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(12,0,1,$m231$يحظر على المتحكم أو المعالج سواء كان شخصا طبيعيا أو اعتباريا جمع بيانات شخصية حساسة أو نقلها أو تخزينها أو حفظها أو معالجتها أو إتاحتها إلا بترخيص من المركز .
وفيما عدا الأحوال المصرح بها قانونا ، يلزم الحصول على موافقة كتابية وصريحة من الشخص المعنى .
وفى حالة إجراء أى عملية مما ذكر تتعلق ببيانات الأطفال ، يلزم موافقة ولى الأمر .
ويجب ألا تكون مشاركة الطفل فى لعبة أو مسابقة أو أى نشاط آخر مشروطة بتقديم بيانات شخصية للطفل تزيد على ما هو ضرورى للمشاركة فى ذلك .
وذلك كله وفقا للمعايير والضوابط التى تحددها اللائحة التنفيذية لهذا القانون .$m231$,'1b6cc1384de1c88bd063dbe049e94b92',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(13,0,1,$m231$بالإضافة إلى الالتزامات الواردة بالمادة (9) من هذا القانون ، يلتزم مسئول حماية البيانات الشخصية وتابعوه لدى المتحكم أو المعالج باتباع واستيفاء السياسات والإجراءات التأمينية اللازمة لعدم خرق البيانات الشخصية الحساسة أو انتهاكها .$m231$,'bb32f8e36a0ffeed05b7374de9998141',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(14,0,1,$m231$يحظر إجراء عمليات نقل للبيانات الشخصية التى تم جمعها أو تجهيزها للمعالجة إلى دولة أجنبية أو تخزينها أو مشاركتها إلا بتوافر مستوى من الحماية لا يقل عن المستوى المنصوص عليه فى هذا القانون ، وبترخيص أو تصريح من المركز .
وتحدد اللائحة التنفيذية لهذا القانون السياسات والمعايير والضوابط والقواعد اللازمة لنقل أو تخزين أو مشاركة أو معالجة أو إتاحة البيانات الشخصية عبر الحدود وحمايتها .$m231$,'377bb637d0b390e17a4ebbc420bb10ec',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(15,0,1,$m231$استثناء من حكم المادة (14) من هذا القانون ، يجوز فى حالة الموافقة الصريحة للشخص المعنى بالبيانات أو من ينوب عنه نقل أو مشاركة أو تداول أو معالجة البيانات الشخصية إلى دولة لا يتوافر فيها مستوى الحماية المشار إليه فى المادة السابقة ، وذلك فى الحالات الآتية :
1 - المحافظة على حياة الشخص المعنى بالبيانات ، وتوفير الرعاية الطبية أو العلاج أو إدارة الخدمات الصحية له .
2 - تنفيذ التزامات بما يضمن إثبات حق أو ممارسته أمام جهات العدالة أو الدفاع عنه .
3 - إبرام عقد ، أو تنفيذ عقد مبرم بالفعل ، أو سيتم إبرامه بين المسئول عن المعالجة والغير ، وذلك لمصلحة الشخص المعنى بالبيانات .
4 - تنفيذ إجراء خاص بتعاون قضائى دولى .
5 - وجود ضرورة أو إلزام قانونى لحماية المصلحة العامة .
6 - إجراء تحويلات نقدية إلى دولة أخرى وفقا لتشريعاتها المحددة والسارية .
7 - إذا كان النقل أو التداول يتم تنفيذا لاتفاق دولى ثنائى أو متعدد الأطراف تكون جمهورية مصر العربية طرفا فيه .$m231$,'b248c780401b6de87387c29e030b9a0b',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(16,0,1,$m231$يجوز للمتحكم أو المعالج ، بحسب الأحوال ، إتاحة البيانات الشخصية لمتحكم أو معالج آخر خارج جمهورية مصر العربية بترخيص من المركز متى توافرت الشروط الآتية :
1 - اتفاق طبيعة عمل كل من المتحكمين أو المعالجين ، أو وحدة الغرض الذى يحصلان بموجبه على البيانات الشخصية .
2 - توافر المصلحة المشروعة لدى كل من المتحكمين أو المعالجين للبيانات الشخصية أو لدى الشخص المعنى بالبيانات .
3 - ألا يقل مستوى الحماية القانونية والتقنية للبيانات الشخصية لدى المتحكم أو المعالج الموجودة بخارج جمهورية مصر العربية عن المستوى المتوافر فى جمهورية مصر العربية .
وتحدد اللائحة التنفيذية لهذا القانون الاشتراطات والإجراءات والاحتياطات والمعايير والقواعد اللازمة لذلك .$m231$,'ae814b35563f2a81fbffefed802e55cf',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(17,0,1,$m231$يحظر إجراء أى اتصال إلكترونى بغرض التسويق المباشر للشخص المعنى بالبيانات ، إلا بتوافر الشروط الآتية :
1 - الحصول على موافقة من الشخص المعنى بالبيانات .
2 - أن يتضمن الاتصال هوية منشئه ومرسله .
3 - أن يكون للمرسل عنوان صحيح وكاف للوصول إليه .
4 - الإشارة إلى أن الاتصال الإلكترونى مرسل لأغراض التسويق المباشر .
5 - وضع آليات واضحة وميسرة لتمكين الشخص المعنى بالبيانات من رفض الاتصال الإلكترونى أو العدول عن موافقته على إرسالها .$m231$,'e3544af2cceda422a21e02637951afd8',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(18,0,1,$m231$يلتزم المرسل لأى اتصال إلكترونى بغرض التسويق المباشر بالالتزامات الآتية :
1 - الغرض التسويقى المحدد .
2 - عدم الإفصاح عن بيانات الاتصال للشخص المعنى بالبيانات .
3 - الاحتفاظ بسجلات إلكترونية مثبت بها موافقة الشخص المعنى بالبيانات وتعديلاتها ، أو عدم اعتراضه على استمراره ، بشأن تلقى الاتصال الإلكترونى التسويقى وذلك لمدة ثلاث سنوات من تاريخ آخر إرسال .
وتحدد اللائحة التنفيذية لهذا القانون القواعد والشروط والضوابط المتعلقة بالتسويق الإلكترونى المباشر .$m231$,'c2e210859b3bc0aec62f510bca0fa093',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(19,0,1,$m231$تنشأ هيئة عامة اقتصادية تسمى «مركز حماية البيانات الشخصية» ، تتبع الوزير المختص ، وتكون لها الشخصية الاعتبارية ، ويكون مقرها الرئيس محافظة القاهرة أو إحدى المحافظات المجاورة لها ، وتهدف إلى حماية البيانات الشخصية وتنظيم معالجتها وإتاحتها ، ولها فى سبيل تحقيق أهدافها أن تباشر جميع الاختصاصات المنصوص عليها بهذا القانون ، ولها على الأخص الآتى :
وضع وتطوير السياسات والخطط الاستراتيجية والبرامج اللازمة لحماية البيانات الشخصية ، والقيام على تنفيذها .
توحيد سياسات وخطط حماية ومعالجة البيانات الشخصية داخل الجمهورية .
وضع وتطبيق القرارات والضوابط والتدابير والإجراءات والمعايير الخاصة بحماية البيانات الشخصية .
وضع إطار إرشادى لمدونات السلوك الخاصة بحماية البيانات الشخصية ، واعتماد مدونات السلوك الخاصة بحماية البيانات الشخصية بالجهات المختلفة .
التنسيق والتعاون مع جميع الجهات والأجهزة الحكومية وغير الحكومية فى ضمان إجراءات حماية البيانات الشخصية ، والتواصل مع جميع المبادرات ذات الصلة .
دعم تطوير كفاءة الكوادر البشرية العاملة فى جميع الجهات الحكومية وغير الحكومية القائمة على حماية البيانات الشخصية .
إصدار التراخيص أو التصاريح والموافقات والتدابير المختلفة المتعلقة بحماية البيانات الشخصية وتطبيق أحكام هذا القانون .
اعتماد الجهات والأفراد ، ومنحهم التصاريح اللازمة التى تتيح لهم تقديم الاستشارات فى إجراءات حماية البيانات الشخصية .
تلقى الشكاوى والبلاغات المتعلقة بأحكام هذا القانون ، وإصدار القرارات اللازمة فى شأنها .
إبداء الرأى فى مشروعات القوانين والاتفاقيات الدولية التى تنظم البيانات الشخصية أو تتعلق أو تنعكس نصوصها بصورة مباشرة أو غير مباشرة عليها .
الرقابة والتفتيش على المخاطبين بأحكام هذا القانون ، واتخاذ الإجراءات القانونية اللازمة .
التحقق من شروط حركة البيانات عبر الحدود ، واتخاذ القرارات المنظمة لها .
تنظيم المؤتمرات وورش العمل والدورات التدريبية والتثقيفية ، وإصدار المطبوعات لنشر الوعى والتثقيف للأفراد والجهات حول حقوقهم فيما يتعلق بالتعامل على البيانات الشخصية .
تقديم جميع أنواع الخبرة والاستشارات المتعلقة بحماية البيانات الشخصية ، وعلى الأخص لجهات التحقيق والجهات القضائية .
إبرام الاتفاقيات ومذكرات التفاهم والتنسيق والتعاون وتبادل الخبرات مع الجهات الدولية ذات الصلة بعمل المركز وفقا للقواعد والإجراءات المقررة فى هذا الشأن .
إصدار الدوريات الخاصة بتحديث إجراءات الحماية بما يتوافق مع أنشطة القطاعات المختلفة وتوصيات المركز فى شأنها .
إعداد وإصدار تقرير سنوى عن حالة حماية البيانات الشخصية فى جمهورية مصر العربية .$m231$,'13f7584f479b503510622e27776c6dbb',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(20,0,1,$m231$يكون للمركز مجلس إدارة ، يشكل برئاسة الوزير المختص ، وعضوية كل من :
1 - ممثل عن وزارة الدفاع يختاره وزير الدفاع .
2 - ممثل عن وزارة الداخلية يختاره وزير الداخلية .
3 - ممثل عن جهاز المخابرات العامة يختاره رئيس الجهاز .
4 - ممثل عن هيئة الرقابة الإدارية يختاره رئيس الهيئة .
5 - ممثل عن هيئة تنمية صناعة تكنولوجيا المعلومات يختاره رئيس مجلس إدارة الهيئة .
6 - ممثل عن الجهاز القومى لتنظيم الاتصالات يختاره رئيس مجلس إدارة الجهاز .
7 - الرئيس التنفيذى للمركز .
8 - ثلاثة من ذوى الخبرة يختارهم الوزير المختص .
وتكون مدة عضوية مجلس الإدارة ثلاث سنوات قابلة للتجديد ، ويصدر بتشكيله ، وتحديد المعاملة المالية لأعضائه قرار من رئيس مجلس الوزراء .
ولمجلس الإدارة أن يشكل من بين أعضائه لجنة أو أكثر يعهد إليها بصفة مؤقتة ببعض المهام ، وللمجلس أن يفوض رئيس مجلس الإدارة أو الرئيس التنفيذى للمركز فى بعض اختصاصاته .$m231$,'5f4630e3b49e111f96b883ed467cd656',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(21,0,1,$m231$مجلس إدارة المركز هو السلطة المهيمنة على شئونه ومباشرة اختصاصاته ، وله أن يتخذ ما يراه لازما من قرارات لتحقيق أغراض المركز والقانون ولائحته التنفيذية وله على الأخص ما يأتى :
إقرار السياسات والخطط الاستراتيجية والبرامج اللازمة لحماية البيانات الشخصية .
اعتماد اللوائح والضوابط والتدابير والمعايير الخاصة بحماية البيانات الشخصية .
اعتماد خطط التعاون الدولى وتبادل الخبرات مع الجهات والمنظمات الدولية .
اعتماد الهيكل التنظيمى واللوائح المالية والإدارية والموارد البشرية والموازنة السنوية للمركز .
الموافقة على إنشاء ، مكاتب أو فروع للمركز على مستوى الجمهورية .
قبول المنح والتبرعات والهبات اللازمة لتحقيق أغراض المركز بعد الحصول على الموافقات المتطلبة قانونا .$m231$,'d563c43137a6ba15327a1015e3d9cd04',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(22,0,1,$m231$يجتمع مجلس إدارة المركز بدعوة من رئيسه مرة على الأقل كل شهر ، وكلما دعت الحاجة لذلك ، ويكون اجتماعه صحيحا بحضور أغلبية أعضائه ، وتصدر قراراته بأغلبية ثلثى أصوات الأعضاء الحاضرين ، وللرئيس أن يدعو من يرى حضور الاجتماع دون أن يكون له صوت معدود .$m231$,'f8cd7d64dedf65d60975645d35305ae3',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(23,0,1,$m231$يكون للمركز رئيس تنفيذى ، يصدر بتعيينه وتحديد معاملته المالية قرار من رئيس مجلس الوزراء بناء على اقتراح الوزير المختص لمدة أربع سنوات قابلة للتجديد لمرة واحدة .
ويكون مسئولا أمام مجلس الإدارة عن سير أعمال المركز فنيا وإداريا وماليا ، ويمثله فى صلاته بالغير وأمام القضاء وله على الأخص ما يأتى :
1 - الإشراف على تنفيذ قرارات مجلس الإدارة .
2 - إدارة المركز والإشراف على سير العمل به ، وتصريف شئونه .
3 - عرض تقارير دورية على مجلس الإدارة عن نشاط المركز وسير العمل به وما تم إنجازه وفقا للأهداف والخطط والبرامج الموضوعة ، وتحديد معوقات الأداء ، والحلول المقترحة لتفاديها .
4 - ممارسة الاختصاصات الأخرى التى تحددها لوائح المركز .
5 - اتخاذ كل ما يلزم لإنفاذ جميع مهام المركز واختصاصاته الواردة فى المادة (21) من هذا القانون .
ويعاون الرئيس التنفيذى فى مباشرة اختصاصاته عدد كاف من الخبراء والفنيين والإداريين وفقا للهيكل التنظيمى للمركز .$m231$,'34925aecacb52d64030c157d89a74ca0',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(24,0,1,$m231$يحظر على أعضاء مجلس إدارة المركز والعاملين به ، إفشاء أى وثائق أو مستندات أو بيانات تتعلق بالحالات التى يقوم المركز برقابتها أو فحصها أو التى يتم تقديمها أو تداولها أثناء فحص أو إصدار القرارات الخاصة بها ، ويظل هذا الالتزام قائما بعد انتهاء العلاقة بالمركز .
وفى جميع الأحوال ، لا يجوز الإفصاح عن المعلومات والوثائق والمستندات والبيانات المشار إليها فى هذه المادة إلا لسلطات التحقيق والجهات والهيئات القضائية .$m231$,'c1d99e36103ec2283ef1439ade9e2c25',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(25,0,1,$m231$للمركز بالتنسيق مع السلطات المختصة التعاون مع نظرائه بالبلاد الأجنبية وذلك فى إطار اتفاقيات التعاون الدولية والإقليمية والثنائية أو بروتوكولات التعاون المصدق عليها أو تطبيقا لمبدأ المعاملة بالمثل بما من شأنه حماية البيانات الشخصية والتحقق من مدى الامتثال للقانون من قبل المتحكمين والمعالجين خارج الجمهورية ، ويعمل المركز على تبادل البيانات والمعلومات بما من شأنه أن يكفل حماية البيانات الشخصية وعدم انتهاكها والمساعدة فى التحقيق فى الانتهاكات والجرائم ذات الصلة وتتبع مرتكبيها .$m231$,'9d3ef19423ad9b3c63d161e817af5bbc',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(26,0,1,$m231$يصدر المركز التراخيص أو التصاريح أو الاعتمادات على النحو الآتى :
1 - يقوم المركز بتصنيف التراخيص والتصاريح والاعتمادات وتحديد أنواعها ، ووضع الشروط الخاصة بمنح كل نوع منها ، وذلك وفقا لما تحدده اللائحة التنفيذية لهذا القانون .
2 - إصدار التراخيص أو التصاريح للمتحكم أو المعالج لإجراء عمليات حفظ البيانات ، والتعامل عليها ومعالجتها وفقا لأحكام هذا القانون .
3 - إصدار التراخيص أو التصاريح الخاصة بالتسويق الإلكترونى المباشر .
4 - إصدار التراخيص أو التصاريح الخاصة بالمعالجات التى تقوم بها الجمعيات أو النقابات أو النوادى للبيانات الشخصية لأعضاء تلك الجهات وفى إطار أنشطتها .
5 - إصدار التراخيص أو التصاريح الخاصة بوسائل المراقبة البصرية فى الأماكن العامة .
6 - إصدار التراخيص أو التصاريح الخاصة بالتحكم أو معالجة البيانات الشخصية الحساسة .
7 - إصدار التصاريح والاعتمادات الخاصة بالجهات والأفراد التى تتيح لهم تقديم الاستشارات فى إجراءات حماية البيانات الشخصية ، وإجراءات الامتثال لها .
8 - إصدار التراخيص والتصاريح الخاصة بنقل البيانات الشخصية عبر الحدود .
وتحدد اللائحة التنفيذية لهذا القانون أنواع هذه التراخيص والتصاريح والاعتمادات وفئاتها ومستوياتها ، وإجراءات وشروط إصدارها وتجديدها ونماذجها المستخدمة ، وذلك بمقابل رسوم لا تتجاوز مليونى جنيه بالنسبة للترخيص ، ومبلغ لا يتجاوز خمسمائة ألف جنيه للتصريح أو الاعتماد .$m231$,'250c2a7da5c08d658ff180962c8647a2',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(27,0,1,$m231$تقدم طلبات التراخيص والتصاريح والاعتمادات على النماذج التى يضعها المركز مشفوعة بجميع المستندات والمعلومات التى يحددها ، مع تقديم ما يثبت قدرة المتقدم المالية وقدرته على توفير وتنفيذ المتطلبات والمعايير الفنية المقررة ، ويبت فى الطلب خلال مدة لا تجاوز تسعين يوما من تاريخ استيفائه لجميع المستندات والمعلومات وإلا اعتبر الطلب مرفوضا .
ويجوز للمركز طلب بيانات أو وثائق أو مستندات أخرى للبت فى الطلب ، كما يكون له الحق فى طلب توفير ضمانات إضافية لحماية البيانات الشخصية إذا تبين عدم كفاية الحماية المبينة بالمستندات المقدمة إليه .
كما يجوز للمتحكم أو المعالج الحصول على أكثر من ترخيص أو تصريح وفقا لنوعية البيانات الشخصية المتعامل عليها .$m231$,'69a00afaa16e07cef22e8f05d5db59b6',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(28,0,1,$m231$يجوز للمركز ، وفقا لاعتبارات المصلحة العامة ، تعديل شروط الترخيص أو التصريح بعد إصداره فى أى من الحالات الآتية :
1 - الاستجابة إلى الاتفاقيات الدولية أو الإقليمية أو القوانين الوطنية ذات الصلة .
2 - بناء على طلب المرخص له .
3 - اندماج المتحكم أو المعالج مع آخرين داخل جمهورية مصر العربية أو خارجها .
4 - إذا كان التعديل ضروريا لتحقيق أهداف هذا القانون .$m231$,'6b514e4b8ff61a9a5dd3404363a5c844',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(29,0,1,$m231$يجوز للمركز إلغاء الترخيص أو التصريح أو الاعتماد بعد إصداره فى أى من الحالات الآتية :
1 - مخالفة شروط الترخيص أو التصريح أو الاعتماد .
2 - عدم سداد رسوم تجديد الترخيص أو التصريح أو الاعتماد .
3 - تكرار عدم الامتثال لقرارات المركز .
4 - التنازل عن الترخيص أو التصريح أو الاعتماد للغير دون موافقة المركز .
5 - صدور حكم بإفلاس المتحكم أو المعالج .$m231$,'2c96e7ad4119aabac6158a0adc212f50',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(30,0,1,$m231$مع عدم الإخلال بأحكام المسئولية المدنية والجنائية ، يقوم الرئيس التنفيذى للمركز ، فى حال ارتكاب أى مخالفة لأحكام هذا القانون بإنذار المخالف بالتوقف عن المخالفة وإزالة أسبابها أو آثارها خلال فترة زمنية يحددها ، فإذا انقضت المدة المشار إليها دون تنفيذ مضمون ذلك الإنذار ، كان لمجلس إدارة المركز أن يصدر قرارا مسببا بما يأتى :
1 - الإنذار بإيقاف الترخيص أو التصريح أو الاعتماد جزئيا أو كليا لمدة محددة .
2 - إيقاف الترخيص أو التصريح أو الاعتماد جزئيا أو كليا .
3 - سحب الترخيص أو التصريح أو الاعتماد أو إلغاؤه جزئيا أو كليا .
4 - نشر بيان بالمخالفات التى ثبت وقوعها فى وسيلة إعلام أو أكثر واسعة الانتشار على نفقة المخالف .
5 - إخضاع المتحكم أو المعالج للإشراف الفنى للمركز لتأمين حماية البيانات الشخصية على نفقتهما بحسب الأحوال .$m231$,'77bf9e4d4b5e04b0dfc9b9d21f047eae',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(31,0,1,$m231$يكون للمركز موازنة خاصة تعد على نمط موازنات الهيئات الاقتصادية طبقا للقواعد التى تحددها لائحة المركز وتتبع قواعد النظام المحاسبى الموحد ، وذلك دون التقيد بالقواعد والنظم الحكومية ، وتبدأ السنة المالية للمركز مع بداية السنة المالية للدولة وتنتهى بنهايتها ، كما يكون للمركز حساب خاص لدى البنك المركزى تودع فيه موارده ، ويجوز له إنشاء حساب باسمه لدى أحد البنوك التجارية بعد موافقة وزير المالية ، ويرحل الفائض من موازنة المركز من سنة مالية إلى أخرى ، ويتم الصرف من موارده وفقا للائحته المالية وذلك فى المجالات التى يحددها مجلس إدارته ، وتتكون موارده من الآتى :
1 - ما يخصص له من موازنة هيئة تنمية صناعة تكنولوجيا المعلومات .
2 - ما يخصص له من الخزانة العامة بما لا يقل عن ثلث حصيلة الغرامات المقضى بها تطبيقا لأحكام هذا القانون .
3 - مقابل الخدمات التى يقوم المركز بتقديمها .
4 - قيمة رسوم ومقابل التراخيص والتصاريح والاعتمادات التى يتم إصدارها وقيمة التصالحات التى يتم قبولها .
5 - عائد استثمار أموال المركز .
6 - ما يقبله مجلس الإدارة من المنح والتبرعات والهبات .$m231$,'fc1836ed384b7e29d7889ae79f83cb8a',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(32,0,1,$m231$يجوز للشخص المعنى بالبيانات ولكل ذى صفة أن يتقدم إلى أى حائز أو متحكم أو معالج بطلب يتعلق بممارسة حقوقه المنصوص عليها فى هذا القانون ، ويلتزم المقدم إليه الطلب بالرد عليه خلال ستة أيام عمل من تاريخ تقديمه إليه .$m231$,'6d72f1d0d866858e36cbeb23d7b80db1',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(33,0,1,$m231$مع عدم الإخلال بالحق فى اللجوء إلى القضاء ، يكون للشخص المعنى بالبيانات ولكل ذى صفة ومصلحة مباشرة حق الشكوى فى الحالات الآتية :
1 - انتهاك حق حماية البيانات الشخصية أو الإخلال به .
2 - الامتناع عن تمكين الشخص المعنى بالبيانات من استيفاء حقوقه .
3 - القرارات الصادرة عن المسئول عن حماية البيانات الشخصية لدى المعالج أو المتحكم بشأن الطلبات المقدمة إليه .
وتقدم الشكوى إلى المركز ، وله فى ذلك اتخاذ ما يلزم من إجراءات التحقيق ، وعليه أن يصدر قراره خلال ثلاثين يوم عمل من تاريخ تقديمها إليه ، على أن يخطر الشاكى والمشكو فى حقه بالقرار .
ويلتزم المشكو فى حقه بتنفيذ قرار المركز خلال سبعة أيام عمل من تاريخ إخطاره به ، وإفادة المركز بما تم نحو تنفيذه .$m231$,'583829804a0294a239de700c0a5ae289',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(34,0,1,$m231$يكون للعاملين بالمركز الذين يصدر بتحديدهم قرار من وزير العدل بناء على اقتراح الوزير المختص صفة الضبطية القضائية فى إثبات الجرائم التى تقع بالمخالفة لأحكام هذا القانون .$m231$,'d8fae169bb2108d869054831cf013d7f',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(35,0,1,$m231$مع عدم الإخلال بأى عقوبة أشد منصوص عليها فى أى قانون آخر ، ومع عدم الإخلال بحق المضرور فى التعويض ، يعاقب على الجرائم المنصوص عليها فى المواد التالية بالعقوبات المقررة لها .$m231$,'0f228e18148298dc512e077532a05129',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(36,0,1,$m231$يعاقب بغرامة لا تقل عن مائة ألف جنيه ولا تجاوز مليون جنيه كل حائز أو متحكم أو معالج جمع أو عالج أو أفشى أو أتاح أو تداول بيانات شخصية معالجة إلكترونيا بأى وسيلة من الوسائل فى غير الأحوال المصرح بها قانونا أو بدون موافقة الشخص المعنى بالبيانات .
وتكون العقوبة الحبس مدة لا تقل عن ستة شهور وبغرامة لا تقل عن مائتى ألف جنيه ولا تجاوز مليونى جنيه ، أو بإحدى هاتين العقوبتين ، إذا ارتكب ذلك مقابل الحصول على منفعة مادية أو أدبية ، أو بقصد تعريض الشخص المعنى بالبيانات للخطر أو الضرر .$m231$,'c6a4fec5d60a8734125c3e4a6c376dee',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(37,0,1,$m231$يعاقب بغرامة لا تقل عن مائة ألف جنيه ولا تجاوز مليون جنيه ، كل حائز أو متحكم أو معالج امتنع دون مقتض من القانون عن تمكين الشخص المعنى بالبيانات من ممارسة حقوقه المنصوص عليها فى المادة (2) من هذا القانون ويعاقب بغرامة لا تقل عن مائتى ألف جنيه ولا تجاوز مليونى جنيه كل من جمع بيانات شخصية بدون توافر الشروط المنصوص عليها فى المادة (3) من هذا القانون .$m231$,'05cc0bd241226972665127ec13795f0f',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(38,0,1,$m231$يعاقب بغرامة لا تقل عن ثلاثمائة ألف جنيه ولا تجاوز ثلاثة ملايين جنيه ، كل متحكم أو معالج لم يلتزم بواجباته المنصوص عليها فى المواد (4 ، 5 ، 7) من هذا القانون .$m231$,'57573a4d4c3c790725dd89ee6a8eb44c',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(39,0,1,$m231$يعاقب بالغرامة التى لا تقل عن مائتى ألف جنيه ولا تجاوز مليونى جنيه ، كل ممثل قانونى للشخص الاعتبارى لم يلتزم بأحد واجباته المنصوص عليها فى المادة (8) من هذا القانون .$m231$,'4ff6e95648872cc5ee68c9d03dc534ad',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(40,0,1,$m231$يعاقب بغرامة لا تقل عن مائتى ألف جنيه ولا تجاوز مليونى جنيه ، كل مسئول حماية بيانات شخصية لم يلتزم بمقتضيات وظيفته المنصوص عليها فى المادة (9) من هذا القانون .
ويعاقب بغرامة لا تقل عن خمسين ألف جنيه ولا تجاوز خمسمائة ألف جنيه إذا وقعت الجريمة نتيجة لإهمال مسئول حماية البيانات الشخصية .$m231$,'f22f495c89938b38dce858bd17a971be',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(41,0,1,$m231$يعاقب بالحبس مدة لا تقل عن ثلاثة شهور وبغرامة لا تقل عن خمسمائة ألف جنيه ولا تجاوز خمسة ملايين جنيه ، أو بإحدى هاتين العقوبتين ، كل حائز أو متحكم أو معالج جمع أو أتاح أو تداول أو عالج أو أفشى أو خزن أو نقل أو حفظ بيانات شخصية حساسة بدون موافقة الشخص المعنى بالبيانات أو فى غير الأحوال المصرح بها قانونا .$m231$,'1bdff2f295f3cabcacfd0f4b128ddc62',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(42,0,1,$m231$يعاقب بالحبس مدة لا تقل عن ثلاثة شهور وبغرامة لا تقل عن خمسمائة ألف جنيه ولا تجاوز خمسة ملايين جنيه ، أو بإحدى هاتين العقوبتين ، كل من خالف أحكام حركة البيانات الشخصية عبر الحدود المنصوص عليها فى المواد (14 ، 15 ، 16) من هذا القانون .$m231$,'f9522190f1d1897e7157a69ee655718b',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(43,0,1,$m231$يعاقب بغرامة لا تقل عن مائتى ألف جنيه ولا تجاوز مليونى جنيه ، كل من خالف أحكام التسويق الإلكترونى المنصوص عليها فى المادتين (17 ، 18) من هذا القانون .$m231$,'f1b26592717bc40930de12a8eed8fcfd',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(44,0,1,$m231$يعاقب بغرامة لا تقل عن ثلاثمائة ألف جنيه ولا تجاوز ثلاثة ملايين جنيه ، كل عضو مجلس إدارة أو أى من العاملين بالمركز خالف الالتزامات المنصوص عليها فى المادة (24) من هذا القانون .$m231$,'67af7c8a2a7ed4422b25fd80c14903a0',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(45,0,1,$m231$يعاقب بغرامة لا تقل عن خمسمائة ألف جنيه ولا تجاوز خمسة ملايين جنيه ، كل من خالف أحكام التراخيص أو التصاريح أو الاعتمادات المنصوص عليها فى هذا القانون .$m231$,'691492c98d64f34deacf75008adfb3a8',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(46,0,1,$m231$يعاقب بالحبس مدة لا تقل عن ستة أشهر وبغرامة لا تقل عن مائتى ألف جنيه ولا تجاوز مليونى جنيه ، أو بإحدى هاتين العقوبتين ، كل من منع أحد العاملين بالمركز ممن يتمتعون بصفة الضبطية القضائية من أداء عمله .$m231$,'71cfdbc500b1a5ee2f507babbdd2f640',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(47,0,1,$m231$يعاقب المسئول عن الإدارة الفعلية للشخص الاعتبارى المخالف بذات العقوبات المقررة عن الأفعال التى ترتكب بالمخالفة لأحكام هذا القانون ، إذا ثبت علمه بها ، وكان إخلاله بالواجبات التى تفرضها عليه تلك الإدارة قد أسهم فى وقوع الجريمة .
ويكون الشخص الاعتبارى مسئولا بالتضامن عن الوفاء بما يحكم به من تعويضات إذا كانت المخالفة قد ارتكبت من أحد العاملين لديه وباسم الشخص الاعتبارى ولصالحه .$m231$,'71fe848da7e81a4d20b980f0a2d67574',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(48,0,1,$m231$فى جميع الأحوال ، وفضلا عن العقوبات المنصوص عليها فى هذا القانون ، تقضى المحكمة بنشر حكم الإدانة فى جريدتين واسعتى الانتشار ، وعلى شبكات المعلومات الإلكترونية المفتوحة على نفقة المحكوم عليه .
وفى حالة العود ، تضاعف العقوبات الواردة فى هذا الفصل بحديها الأقصى والأدنى .
ويعاقب على الشروع فى ارتكاب الجرائم المنصوص عليها فى هذا القانون بنصف العقوبة المقررة لها .$m231$,'2a1a1d1986feb68ccef41740dbae99e9',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL),
(49,0,1,$m231$يجوز للمتهم فى أى حالة كانت عليها الدعوى الجنائية ، وقبل صيرورة الحكم باتا ، إثبات الصلح مع المجنى عليه أو وكيله الخاص أو خلفه العام ، وبموافقة المركز أمام النيابة العامة أو المحكمة المختصة بحسب الأحوال ، وذلك فى الجنح المنصوص عليها فى المواد (36 ، 37 ، 38 ، 39 ، 40 ، 41 ، 43) من هذا القانون .
ويكون التصالح مع المركز فى الجنح المنصوص عليها بالمواد (42 ، 44 ، 45) من هذا القانون فى أى حالة كانت عليها الدعوى .
وفى جميع الأحوال ، يجب على المتهم الذى يرغب فى التصالح أن يسدد قبل رفع الدعوى الجنائية مبلغا يعادل نصف الحد الأدنى للغرامة المقررة للجريمة .
ويسدد المتهم راغب التصالح بعد رفع الدعوى وقبل صيرورة الحكم باتا نصف الحد الأقصى للغرامة المقررة للجريمة ، أو قيمة الغرامة المقضى بها أيهما أكبر .
ويكون السداد فى خزانة المحكمة المختصة أو النيابة العامة أو المركز بحسب الأحوال .
ويترتب على التصالح انقضاء الدعوى الجنائية دون أن يكون له أثر على حقوق المضرور من الجريمة .$m231$,'6e6b1838bdfdf0659d181ad2d64fd3bb',DATE '2020-10-16',NULL,'active',NULL,NULL,NULL);

DO $m231$
DECLARE
  v_law uuid;
  v_title text;
  v_new_law boolean := false;
  v_ins_art int;
  v_ins_ver int;
  v_cnt int;
  v_vcnt int;
BEGIN
  IF (SELECT count(*) FROM m231_art WHERE md5(body) <> body_md5) <> 0 OR (SELECT count(*) FROM m231_ver WHERE md5(body) <> body_md5) <> 0 THEN
    RAISE EXCEPTION '[231] تلف فى نص أحد الصفوف داخل الملف';
  END IF;
  IF (SELECT count(*) FROM m231_art) <> 57 OR (SELECT sum(char_length(body)) FROM m231_art) <> 34607 OR (SELECT count(*) FROM m231_ver) <> 57 THEN
    RAISE EXCEPTION '[231] عدد الصفوف أو النسخ أو طول النص داخل الملف غير مطابق';
  END IF;

  SELECT id, title INTO v_law, v_title FROM laws WHERE country_code='EG' AND law_no=151 AND law_year=2020 AND kind='law';
  IF v_law IS NOT NULL AND v_title NOT LIKE '%حماية البيانات الشخصية%' THEN
    RAISE EXCEPTION '[231] يوجد مستند آخر برقم 151 لسنة 2020 (%): لا يُدمج هذا النص فيه', v_title;
  END IF;
  IF v_law IS NULL THEN
    INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at, last_amended_at, country_code, kind, governance_scope)
    VALUES (151, 2020, $t231$قانون رقم 151 لسنة 2020 بإصدار قانون حماية البيانات الشخصية$t231$, $t231$قانون حماية البيانات الشخصية 151/2020$t231$, 'other', 'in_force', NULL, DATE '2020-07-13', NULL, 'EG', 'law', false)
    RETURNING id INTO v_law;
    v_new_law := true;
  END IF;

  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, body)
  SELECT v_law, article_no, suffix, loc, body FROM m231_art
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING;
  GET DIAGNOSTICS v_ins_art = ROW_COUNT;

  INSERT INTO article_versions (article_id, version_no, body, effective_from, effective_to, status, amended_by_law_no, amended_by_law_year, change_note)
  SELECT a.id, m.version_no, m.body, m.eff, m.eff_to, m.status, m.am_no, m.am_yr, m.note
    FROM articles a JOIN m231_ver m ON m.article_no = a.article_no AND m.suffix = a.article_suffix_order
   WHERE a.law_id = v_law
     AND NOT EXISTS (SELECT 1 FROM article_versions v WHERE v.article_id = a.id)
  ON CONFLICT (article_id, version_no) DO NOTHING;
  GET DIAGNOSTICS v_ins_ver = ROW_COUNT;

  SELECT count(*) INTO v_cnt FROM articles a JOIN m231_art m ON m.article_no=a.article_no AND m.suffix=a.article_suffix_order
   WHERE a.law_id=v_law;
  IF v_cnt <> 57 THEN
    RAISE EXCEPTION '[231] عدد صفوف النص % بدل 57', v_cnt;
  END IF;
  SELECT count(*) INTO v_vcnt FROM article_versions v JOIN articles a ON a.id=v.article_id WHERE a.law_id=v_law;
  IF v_vcnt <> 57 THEN
    RAISE EXCEPTION '[231] عدد نسخ النص % بدل 57', v_vcnt;
  END IF;
  RAISE NOTICE '[231] قانون 151/2020: جديد=%، صفوف مضافة=%، نسخ مضافة=%', v_new_law, v_ins_art, v_ins_ver;
END
$m231$;
